import { useEffect, useRef, useState } from 'react'
import { ArrowLeft, ArrowRight, Bell, BookOpen, ChevronRight, CircleHelp, Compass, Home, Leaf, Map, Menu, Mic, Pause, Play, RotateCcw, Sparkles, TreePine, Utensils, Volume2, X } from 'lucide-react'
import { animals, chapters, Page, points, nodeMissions, rewards } from './data'
import { answerFromKnowledge } from './services/ragService'
import { generateStory, GeneratedStory, StoryMode, storyModeOptions } from './services/storyService'
import { planRoute, askCompanion, synthesizeSpeech, generateStory as generateStoryApi } from './services/backendApi'
import officialMap from './assets/hongshan-official-map.jpg'
import './official-map.css'
import PlanV6 from './PlanV6'

const initial = (localStorage.getItem('hs-state') || '')
let latestBack:()=>void=()=>{}
let latestGo:(page:Page)=>void=()=>{}
let latestState:any=null
// Fallback persistence helper used by the legacy growth view kept for backwards compatibility.
const setS = (fn:(value:State)=>State) => { const raw=localStorage.getItem('hs-state'); if(raw){localStorage.setItem('hs-state',JSON.stringify(fn(JSON.parse(raw)))); window.location.reload()} }
type PlayHistory={id:string;date:string;companion:string;routeMode:string;points:string[];clues:number;score:number;storyStyle?:string}
type State={page:Page; quiz:number; companion:number; routeMode:string; active:number; completed:boolean; adjustment:string|null; answers:string[]; clues:string[]; stamps:string[]; score:number; npcTasks:number[]; redeemed:string[]; preference:string; history?:PlayHistory[]}
function App(){
 const [s,setS]=useState<State>(initial?{answers:[],clues:[],stamps:[],score:0,npcTasks:[],redeemed:[],preference:'',...JSON.parse(initial)}:{page:'welcome',quiz:0,companion:0,routeMode:'轻松亲子线',active:0,completed:false,adjustment:null,answers:[],clues:[],stamps:[],score:0,npcTasks:[],redeemed:[],preference:''})
 latestState=s
 useEffect(()=>localStorage.setItem('hs-state',JSON.stringify(s)),[s])
 const pageHistory=useRef<Page[]>([])
 const currentPage=useRef<Page>(s.page)
 const restoringBack=useRef(false)
 useEffect(()=>{if(currentPage.current!==s.page){if(restoringBack.current){restoringBack.current=false}else{pageHistory.current.push(currentPage.current)}currentPage.current=s.page}},[s.page])
 const go=(page:Page)=>setS(v=>({...v,page}))
 latestGo=go
 const back=()=>setS(v=>{const previous=pageHistory.current.pop();if(previous){restoringBack.current=true;return {...v,page:previous}};const fallback:Record<Page,Page>={welcome:'welcome',quiz:'welcome',match:'home',home:'welcome',plan:'home',route:'plan',story:'route',tour:'story',venue:'tour',complete:'home',growth:'home',ask:'tour'};const target=fallback[v.page];if(target&&target!==v.page)return {...v,page:target};return v})
 latestBack=back
 if(s.page==='welcome') return <WelcomeV2 go={go}/>
 if(s.page==='quiz') return <Quiz s={s} setS={setS}/>
 return <Shell s={s} go={go}><>{s.page==='match'&&<Match s={s} setS={setS} go={go}/>} {s.page==='home'&&<HomePageV2 s={s} go={go}/>} {s.page==='plan'&&<PlanV6 s={s} setS={setS}/>} {s.page==='route'&&<RoutePageV2 s={s} setS={setS} go={go}/>} {s.page==='story'&&<StoryGeneratorPage s={s} go={go}/>} {s.page==='tour'&&<TourV2 s={s} setS={setS} go={go}/>} {s.page==='venue'&&<VenueV4 s={s} setS={setS} go={go}/>} {s.page==='complete'&&<Complete go={go}/>} {s.page==='growth'&&<GrowthV3 s={s} go={go}/>} {s.page==='ask'&&<AskV2 go={go}/>}</></Shell>
}
function Welcome({go}:{go:(p:Page)=>void}){return <div className="welcome page"><div className="mist mist1"/><div className="mist mist2"/><div className="brand"><div className="brand-mark"><TreePine size={30}/></div><span>有温度的智能游伴</span></div><div className="welcome-copy"><p className="eyebrow">NANJING · HONGSHAN</p><h1>山野游伴</h1><p>让红山的故事，陪你走完整段旅程</p><div className="value"><Leaf size={17}/> 动物是这里的主人，游客是来访的客人</div></div><div className="welcome-companion"><Companion3D size="normal"/><span>你好，我是团团</span></div><div className="welcome-actions"><button className="primary" onClick={()=>go('quiz')}>开始认识你的游伴 <ArrowRight size={18}/></button><button className="ghost" onClick={()=>go('plan')}>直接规划路线</button></div><small>小程序创意原型 · 赛事作品<br/>非园区官方推荐</small></div>}
function Shell({s,go,children}:{s:State;go:(p:Page)=>void;children:React.ReactNode}){return <div className="app"><header className="topbar"><button className="icon-btn" onClick={()=>go(s.page==='home'?'welcome':'home')}><ArrowLeft size={18}/></button><span className="top-title">{s.page==='growth'?'我的游伴':s.page==='tour'?'正在游览':s.page==='venue'?'到达场馆':s.page==='route'?'今日路线':'山野游伴'}</span><button className="icon-btn"><Menu size={19}/></button></header><main>{children}</main>{!['tour','venue','complete','route','story','plan'].includes(s.page)&&<nav><button className={s.page==='home'?'on':''} onClick={()=>go('home')}><Home/><span>首页</span></button><button className={s.page==='plan'?'on':''} onClick={()=>go('plan')}><Map/><span>行程</span></button><button className={s.page==='growth'?'on':''} onClick={()=>go('growth')}><Compass/><span>游伴</span></button><button><CircleHelp/><span>我的</span></button></nav>}</div>}
function Companion3D({size='normal'}:{size?:'tiny'|'small'|'normal'}){return <div className={`companion-3d ${size}`} aria-label="团团，红山小熊猫游伴"><div className="companion-shadow"/><div className="companion-tail"/><div className="companion-body"><div className="companion-ear left"/><div className="companion-ear right"/><div className="companion-face"><i className="eye left"/><i className="eye right"/><i className="cheek left"/><i className="cheek right"/><span className="nose"/><span className="mouth"/></div><div className="companion-paw left"/><div className="companion-paw right"/></div></div>}
function HomePage({go}:{s:State;go:(p:Page)=>void}){return <div className="page home-page"><div className="greeting"><div><p className="eyebrow">2026年7月28日 · 周二</p><h2>下午好，团团的伙伴</h2><p>今天树荫下比较舒服，适合一段慢节奏的林间路线。</p></div><div className="sun">☼</div></div><div className="weather"><span>☀ 29°</span><span>体感 31°</span><span>园区舒适</span><b>模拟实时数据</b></div><section className="hero-card"><div className="hero-art"><div className="sun-art"/><div className="hill h1"/><div className="hill h2"/><TreePine className="tree t1"/><TreePine className="tree t2"/><Companion3D size="small"/></div><div className="hero-body"><p className="eyebrow">TODAY'S ROUTE</p><h3>为今天规划一条专属路线</h3><div className="stats"><span><b>2h</b>预计耗时</span><span><b>低</b>拥挤程度</span><span><b>3.2km</b>步行距离</span></div><button className="primary" onClick={()=>go('plan')}>开始规划 <ArrowRight size={17}/></button></div></section><div className="section-head"><h3>今日动物动态</h3><span>模拟实时数据</span></div><div className="animal-row">{animals.slice(0,2).map(a=><div className="animal-card" key={a.name}><div className="animal-avatar" style={{background:a.color}}>{a.name==='团团'?<Companion3D size="tiny"/>:a.emoji}</div><div><b>{a.name}</b><p>{a.active}</p></div><span className="dot"/></div>)}</div><div className="story-mini" onClick={()=>go('story')}><div><p className="eyebrow">今日红山故事</p><h3>寻找森林里消失的歌声</h3><p>有些声音，要等你安静下来才会出现。</p></div><BookOpen size={24}/></div></div>}
function Quiz({s,setS}:{s:State;setS:React.Dispatch<React.SetStateAction<State>>}){const qs: [string,string[]][]=[['你更喜欢哪种颜色？',['苔藓绿','落日橙','晨雾灰']],['你最喜欢哪个季节？',['春天的风','夏日树荫','秋天的果实']],['你更向往哪种自然景观？',['森林树荫','溪流湿地','山野草坡']],['周末你更愿意做什么？',['慢慢散步','寻找惊喜','坐下听故事']],['遇到陌生环境时，你通常怎么做？',['先观察一会儿','带着好奇探索','和伙伴一起行动']]]; const q=qs[s.quiz]; return <div className="quiz page"><div className="quiz-top"><button className="icon-btn" onClick={()=>s.quiz?setS(v=>({...v,quiz:v.quiz-1})):setS(v=>({...v,page:'welcome'}))}><ArrowLeft/></button><span>{s.quiz+1} / 5</span><button className="skip" onClick={()=>setS(v=>({...v,page:'home',companion:0}))}>跳过</button></div><div className="progress"><i style={{width:`${(s.quiz+1)*20}%`}}/></div><div className="quiz-copy"><p className="eyebrow">MEET YOUR COMPANION</p><h1>{q[0]}</h1><p>选一个最接近此刻的答案，不需要想太久。</p></div><div className="option-list">{q[1].map((o,i)=><button key={o} className="option" onClick={()=>s.quiz===4?setS(v=>({...v,page:'growth',quiz:0,companion:0})):setS(v=>({...v,quiz:v.quiz+1}))}><span>0{i+1}</span>{o}<ChevronRight size={18}/></button>)}</div><div className="quiz-leaf"><Leaf size={17}/> 你的答案只会用来生成更贴合你的游伴</div></div>}
function Plan({s,setS}:{s:State;setS:React.Dispatch<React.SetStateAction<State>>}){const [step,setStep]=useState(0); const vals=[['可用时间','2小时'],['体力状态','轻松'],['同行伙伴','带着3岁孩子'],['动物偏好','灵长类'],['特别在意','中途休息 · 怕晒']];return <div className="page plan-page"><div className="plan-head"><p className="eyebrow">ROUTE AGENT · 正在了解你</p><h1>今天想怎么逛？</h1><p>不用做攻略，告诉我几个小偏好就好。</p></div><div className="chat-bubble">我带着3岁孩子，只有2小时，不想爬山，希望中途能休息一下。<span>刚刚</span></div><div className="plan-fields">{vals.map(([a,b],i)=><button className="field" key={a} onClick={()=>setStep(i)}><span>{a}</span><b>{b}</b><ChevronRight size={17}/></button>)}</div><div className="nature-input"><Mic size={18}/><span>还有什么想告诉我？</span><button>语音输入</button></div><button className="primary full" onClick={()=>{setS(v=>({...v,page:'route'}));}}>生成我的路线 <Sparkles size={17}/></button><p className="privacy"><Leaf size={13}/> 仅使用本地模拟数据 · 不连接外部服务</p></div>}
function RoutePage({s,setS,go}:{s:State;setS:React.Dispatch<React.SetStateAction<State>>;go:(p:Page)=>void}){return <div className="page route-page"><div className="route-intro"><p className="eyebrow">ROUTE AGENT · 已为你准备好</p><h1>轻松亲子线</h1><p>让脚步慢下来，故事才会跟上来。</p></div><div className="route-summary"><span><b>2h</b>预计耗时</span><span><b>3.2km</b>步行距离</span><span><b>低</b>拥挤程度</span><span><b>72%</b>树荫覆盖</span></div><div className="map-card"><MapArt active={s.active}/><div className="map-label">模拟园区地图 · 推荐路线</div></div><div className="why"><h3>为什么这样推荐？</h3><p>因为你不想爬山，我们降低了高坡路线权重；因为带着孩子，控制了连续步行时长；因为怕晒，优先选择树荫道路；也因为喜欢灵长类，先去亚洲灵长馆。</p></div><div className="route-points">{points.slice(0,5).map((p,i)=><div className="point" key={p.id}><div className="point-num">{i+1}</div><div><b>{p.name}</b><p>{i===0?'09:30':i===1?'09:48':i===2?'10:12':i===3?'10:42':'11:08'} · 停留 {i===2?'25':'15'} 分钟</p></div><span className="point-tag">{i===2?'灵长类':'树荫'}</span></div>)}</div><button className="primary full" onClick={()=>go('story')}>听听这条路线的故事 <BookOpen size={17}/></button><button className="secondary full" onClick={()=>setS(v=>({...v,page:'route',routeMode:'动物活跃优先线'}))}>换一条路线 <RotateCcw size={16}/></button></div>}
function MapArt({active}:{active:number}){const [selected,setSelected]=useState<number|null>(null);const point=selected===null?null:points[selected];return <div className="map-art official-map-art"><img className="official-map-image" src={officialMap} alt="红山森林动物园官方导览图"/><div className="official-map-tint"/><div className="official-route-line"/>{points.map((p,i)=><button type="button" key={p.id} aria-label={`查看${p.name}介绍`} className={`map-point ${i===active?'active':''} ${selected===i?'selected':''}`} style={{left:`${p.x}%`,top:`${p.y}%`}} onClick={()=>setSelected(i)}><span>{i+1}</span></button>)}{point&&<div className="map-point-popover" onClick={e=>e.stopPropagation()}><button className="map-popover-close" onClick={()=>setSelected(null)}>×</button><p className="eyebrow">点位 {selected!+1}</p><h3>{point.name}</h3><p>{point.sub}</p><small>点击下方进入这一站的专属讲解，先观察，再听故事。</small><button className="secondary full" onClick={()=>{const raw=localStorage.getItem('hs-state');if(raw){const next={...JSON.parse(raw),active:selected,page:'venue'};localStorage.setItem('hs-state',JSON.stringify(next))}latestGo('venue')}}>查看点位讲解 <ArrowRight size={14}/></button></div>}</div>}
function Story({go}:{go:(p:Page)=>void}){return <div className="page story-page"><div className="story-cover"><div className="cover-noise"/><p className="eyebrow">TODAY'S STORY · 01</p><h1>寻找森林里<br/>消失的歌声</h1><p>一封来自森林的信，正在等你听见。</p><span className="cover-tree">♧</span></div><div className="chapter"><p className="eyebrow">序章 · 游伴团团</p><h2>“你听，风里是不是藏着一段旋律？”</h2><p>团团把一片叶子递到你手里。它说，今天的路线里藏着四个线索。别急着找到它，先让自己成为森林的一部分。</p></div><div className="chapter-list">{chapters.map((x,i)=><div key={x} className="chapter-item"><span>0{i+1}</span><b>{x}</b><ChevronRight size={17}/></div>)}</div><button className="primary full" onClick={()=>go('tour')}>带着这个故事出发 <ArrowRight size={17}/></button><button className="text-btn" onClick={()=>go('route')}>切换为普通路线</button></div>}
function Tour({s,setS,go}:{s:State;setS:React.Dispatch<React.SetStateAction<State>>;go:(p:Page)=>void}){const p=points[s.active]; const [modal,setModal]=useState(false); return <div className="page tour-page"><div className="tour-status"><div><p className="eyebrow">轻松亲子线 · {s.active+1}/5</p><h2>已游览 42 分钟</h2></div><div className="time"><b>1h18</b><small>剩余时间</small></div></div><div className="tour-alert"><Bell size={17}/><span><b>下一站：{p.name}</b><small>{p.sub}</small></span><ChevronRight size={17}/></div><div className="tour-map"><MapArt active={s.active}/><div className="location">当前位置 · 林间小径</div></div><div className="now-card"><div className="now-icon"><Leaf/></div><div><p className="eyebrow">正在前往</p><h3>{p.name}</h3><p>距离 380m · 预计 8 分钟</p></div><button className="icon-btn"><Volume2 size={18}/></button></div><div className="companion-line"><Companion3D size="tiny"/><p>“不用赶路，树荫下的每一步都算数。”</p></div><div className="quick-actions">{[['疲惫了','rest'],['饿了','food'],['这里想多待','wait'],['人有点多','crowd']].map(([x,id])=><button key={id} onClick={()=>setModal(true)}>{id==='food'?<Utensils/>:<Leaf/>}<span>{x}</span></button>)}</div><div className="tour-bottom"><button className="primary full" onClick={()=>{if(s.active>=4)go('complete');else setS(v=>({...v,active:v.active+1}))}}>{s.active>=4?'完成游览':'到达下一站'} <ArrowRight size={17}/></button><button className="secondary full" onClick={()=>setModal(true)}>触发演示事件</button></div>{modal&&<div className="modal-backdrop"><div className="modal"><button className="close" onClick={()=>setModal(false)}><X/></button><div className="modal-icon"><Sparkles/></div><h2>线路小调整</h2><p>亚洲灵长馆当前预计等待 25 分钟。要不要先去附近的林间休息区？你的灵长类偏好会被保留。</p><div className="diff"><span>原路线 <b>灵长馆</b></span><ArrowRight/><span>调整后 <b>休息区 → 灵长馆</b></span></div><button className="primary full" onClick={()=>{setModal(false);setS(v=>({...v,adjustment:'已插入休息区'}))}}>先去附近场馆</button><button className="text-btn" onClick={()=>setModal(false)}>维持原计划</button></div></div>}</div>}
function Venue({s,go}:{s:State;go:(p:Page)=>void}){return <div className="page venue-page"><div className="venue-hero"><div className="venue-symbol">◒</div><p className="eyebrow">刚刚到达 · 模拟实时数据</p><h1>亚洲灵长馆</h1><div className="active-chip"><i/> 当前活跃度较高 · 推荐观赏位东侧</div></div><div className="audio-card"><button className="play"><Play fill="currentColor"/></button><div><b>播放亲子故事版</b><p>森林里的邻居 · 02:38</p></div><div className="audio-line"><i/></div></div><div className="version"><span>讲解版本</span><button className="selected">亲子故事</button><button>轻松版</button><button>动物福利</button></div><div className="script"><p>团团的观察笔记</p><h2>先别急着寻找它们。</h2><p>站在树荫下听一会儿，也许你会先听见声音，再看见身影。在这里，动物不需要随时出现在游客面前。</p><div className="observe"><Leaf size={18}/><span><b>不打扰地观察</b><small>不敲玻璃 · 不投喂 · 不使用强闪光</small></span></div></div><button className="primary full" onClick={()=>go('tour')}>继续我的路线 <ArrowRight size={17}/></button></div>}
function Complete({go}:{go:(p:Page)=>void}){return <div className="page complete-page"><div className="complete-mark"><Leaf size={32}/></div><p className="eyebrow">A GENTLE DAY IN HONGSHAN</p><h1>今天，你没有<br/>赶完所有地方。</h1><p className="lead">但你认真听完了三段故事，<br/>也给森林留下了一点安静。</p><div className="score"><b>+40</b><span>今日成长值</span><div className="score-line"><i/></div></div><div className="gains"><span>完成主要路线 <b>+20</b></span><span>收听场馆故事 <b>+15</b></span><span>文明观察互动 <b>+5</b></span></div><button className="primary full" onClick={()=>go('growth')}>看看团团的成长 <ArrowRight size={17}/></button><button className="secondary full" onClick={()=>go('home')}>回到首页</button></div>}
function Growth({go}:{go:(p:Page)=>void}){return <div className="page growth-page"><div className="growth-head"><Companion3D size="normal"/><div><p className="eyebrow">你的动物游伴</p><h1>团团</h1><p>考拉式慢游伴 · Lv.2</p></div><span className="badge">观察者</span></div><div className="level"><div><b>慢慢长大中</b><span>40 / 100</span></div><div className="level-line"><i/></div><small>再听两段故事，解锁“森林回声”</small></div><div className="growth-grid"><div><b>3</b><span>听过的故事</span></div><div><b>2</b><span>走过的场馆</span></div><div><b>4.2km</b><span>温柔步行</span></div></div><section className="unlock"><p className="eyebrow">已解锁</p><h3>森林里的第一封信</h3><p>你愿意放慢脚步，故事才开始写下去。</p></section><section className="locked"><div className="lock">⌁</div><div><b>今日红山故事</b><p>每日一段，等你来听</p></div><span>待解锁</span></section><section className="locked"><div className="toy">♧</div><div><b>毛绒玩具绑定</b><p>未来功能 · 概念展示</p></div><span>未来</span></section><button className="secondary full" onClick={()=>go('home')}>回到首页</button></div>}
function GrowthOrMatch({s,setS,go}:{s:State;setS:React.Dispatch<React.SetStateAction<State>>;go:(p:Page)=>void}){return s.companion===0?<Match s={s} setS={setS} go={go}/>:<Growth go={go}/>}
function Match({s,setS,go}:{s:State;setS:React.Dispatch<React.SetStateAction<State>>;go:(p:Page)=>void}){const pick=(i:number,blind=false)=>setS(v=>({...v,companion:i,page:'home',routeMode:'轻松亲子线',answers:blind?['盲盒相遇']:v.answers}));return <div className="page match-page"><p className="eyebrow">COMPANION ADOPTION · MATCHED FOR YOU</p><h1>你的森林搭子，<br/>正在等你领养</h1><p className="match-lead">根据你的回答，我为你挑出了三种不同的相处方式。也可以把选择交给红山的盲盒。</p><div className="match-card featured"><div className="match-visual"><Companion3D size="normal"/></div><div className="match-content"><span className="match-label">最适合你</span><h2>{animals[0].name}</h2><p>{animals[0].type} · {animals[0].species}</p><div className="tag-row">{animals[0].tags.map(x=><span key={x}>{x}</span>)}</div><blockquote>“{animals[0].quote}”</blockquote><button className="primary full" onClick={()=>pick(0)}>领养团团 <HeartIcon/></button></div></div><p className="other-title">或者看看其他搭子</p><div className="other-matches">{animals.slice(1).map((a,i)=><button key={a.name} onClick={()=>pick(i+1)}><div className="match-dot" style={{background:a.color}}>{a.emoji}</div><span><b>{a.name}</b><small>{a.type}</small></span><ChevronRight size={16}/></button>)}</div><button className="blind-box" onClick={()=>pick(Math.floor(Math.random()*animals.length),true)}><Sparkles size={18}/><span><b>盲盒领养</b><small>把相遇交给今天的运气</small></span><ChevronRight size={18}/></button></div>}
function HeartIcon(){return <span className="heart">♥</span>}
function WelcomeV2({go}:{go:(p:Page)=>void}){return <div className="welcome page"><div className="mist mist1"/><div className="mist mist2"/><div className="brand"><div className="brand-mark"><TreePine size={30}/></div><span>有温度的智能游伴</span></div><div className="welcome-copy"><p className="eyebrow">NANJING · HONGSHAN</p><h1>山野游伴</h1><p>让红山的故事，陪你走完整段旅程</p><div className="value"><Leaf size={17}/> 动物是这里的主人，游客是来访的客人</div></div><div className="welcome-companion"><Companion3D size="normal"/><span>你好，我是你的森林搭子</span></div><div className="welcome-actions"><button className="primary" onClick={()=>go('quiz')}>回答几个问题，领养搭子 <ArrowRight size={18}/></button><button className="ghost" onClick={()=>go('match')}>不想答题？直接开盲盒 <Sparkles size={17}/></button><button className="text-btn welcome-blind" onClick={()=>go('plan')}>先规划路线</button></div><small>小程序创意原型 · 赛事作品<br/>非园区官方推荐</small></div>}
function CompanionStory({s,go}:{s:State;go:(p:Page)=>void}){const a=animals[s.companion]||animals[0];return <div className="page story-page"><div className="story-cover companion-story-cover"><Companion3D size="normal"/><p className="eyebrow">{a.name} 的今日故事 · 01</p><h1>{a.story}</h1><p>这一次，故事从你的搭子选择停下来的地方开始。</p></div><div className="chapter"><p className="eyebrow">序章 · {a.name} 写给你的信</p><h2>“{a.quote}”</h2><p>{a.species}不需要被安排成一场表演。{a.name}想带你去看一处适合慢慢观察的地方：先留出距离，听一会儿，再决定要不要靠近。</p></div><div className="chapter-list">{chapters.map((x,i)=><div key={x} className="chapter-item"><span>0{i+1}</span><b>{i===0?`${a.name} 在入口留下的线索` : x}</b><ChevronRight size={17}/></div>)}</div><button className="primary full" onClick={()=>go('tour')}>带着 {a.name} 出发 <ArrowRight size={17}/></button><button className="text-btn" onClick={()=>go('route')}>切换为普通路线</button></div>}
function Ask({go}:{go:(p:Page)=>void}){const [q,setQ]=useState('');const [result,setResult]=useState<ReturnType<typeof answerFromKnowledge>|null>(null);const ask=(text=q)=>{if(text.trim())setResult(answerFromKnowledge(text))};return <div className="page ask-page"><p className="eyebrow">LOCAL RAG · 红山知识库</p><h1>问问红山</h1><p className="ask-lead">关于动物、场馆、保育和文明观察，你可以问得更具体一点。回答只来自本地官方素材。</p><div className="ask-input"><input value={q} onChange={e=>setQ(e.target.value)} onKeyDown={e=>e.key==='Enter'&&ask()} placeholder="例如：貉什么时候更活跃？"/><button onClick={()=>ask()}><ArrowRight size={18}/></button></div><div className="suggestions">{['貉什么时候更活跃？','为什么不能敲玻璃？','一个池塘是怎么自循环的？'].map(x=><button key={x} onClick={()=>{setQ(x);ask(x)}}>{x}</button>)}</div>{result&&<div className="rag-result"><div className="rag-badge"><BookOpen size={15}/> 已检索本地知识库</div><p>{result.answer}</p>{result.sources.map(x=><div className="source" key={x.id}><b>{x.title}</b><small>{x.source}</small></div>)}</div>}<button className="secondary full ask-back" onClick={()=>go('home')}>回到首页</button></div>}
function CompanionStoryV2({s,go}:{s:State;go:(p:Page)=>void}){const a=animals[s.companion]||animals[0];const [mode,setMode]=useState<'quiet'|'clue'|null>(null);const scene=a.species==='貉'?{place:'本土物种保育区 · 荒丘野地',hook:'落叶堆里，少了一颗种子。',clue:'貉把食物藏起来，却没有回来取。也许森林正在替它保管一个秘密。',fact:'貉在清晨和黄昏更活跃，也是会帮助传播种子的“城市邻居”。',ending:'你没有追上它，但在落叶下发现了一株刚冒头的小树。'}:a.species==='赤狐'?{place:'本土物种保育区 · 山林边缘',hook:'那道红色身影，为什么停在了距离你三步远的地方？',clue:'麦穗没有靠近。它在确认你会不会把安静还给它。',fact:'救助后的赤狐仍然需要保有野生动物的边界；保护不是驯服，而是尊重。',ending:'你站在原地，麦穗转身跑进林缘。那一刻，你们都拥有了自己的自由。'}:a.species==='獐'?{place:'本土物种保育区 · 一个池塘',hook:'池塘里没有人投喂，却一直保持着自己的秩序。',clue:'獐灯带你看一圈水面：鱼、虾、螺和植物，谁也不是配角。',fact:'植物、虾螺、小鱼和肥料循环共同维持池塘生态，形成不依赖人工投喂的自循环。',ending:'你终于明白，森林的故事不是谁最耀眼，而是谁愿意把自己的位置让给别人。'}:{place:'熊猫馆 · 室外活动场',hook:'平平、和和、九九，为什么没有住在一起？',clue:'团团让你先看天气，再看场馆：动物会自己选择舒服的地方。',fact:'熊猫馆依据大熊猫的自然习性设置室内外空间，并尊重其独居和领地需求。',ending:'你没有等到它们一直面对游客的画面，却看见了更重要的事：它们可以按自己的节奏生活。'};return <div className="page story-page story-v2"><div className="story-v2-hero"><div className="story-v2-orbit"/><Companion3D size="normal"/><div className="story-v2-kicker">{a.name} 的今日任务 · 01</div><h1>{scene.hook}</h1><p>一条路线，三个线索。你愿意用哪种方式陪它走完？</p></div><div className="story-progress"><span className="active"/><span/><span/><b>1 / 3</b></div><div className="story-v2-intro"><span className="scene-pin">●</span><div><p className="eyebrow">第一站 · {scene.place}</p><h2>{a.name} 把你带到这里</h2><p>它没有催你靠近，只把一片叶子放在路边。你发现，真正的线索往往不在玻璃里面，而在你愿意停下来的那几秒。</p></div></div><div className="story-choice"><p className="eyebrow">选择你的观察方式</p><button className={mode==='quiet'?'chosen':''} onClick={()=>setMode('quiet')}><span>A</span><div><b>安静等一等</b><small>把主动权交还给动物</small></div><ChevronRight size={17}/></button><button className={mode==='clue'?'chosen':''} onClick={()=>setMode('clue')}><span>B</span><div><b>沿着线索走</b><small>看看这片生境藏着什么</small></div><ChevronRight size={17}/></button></div>{mode&&<div className="story-reveal"><div className="reveal-label"><Sparkles size={14}/> {mode==='quiet'?'你选择了等待':'你选择了探索'}</div><h3>{mode==='quiet'?'安静不是空白，是给森林留出的发言时间。':'线索没有把你带向一个表演，而是带向一段关系。'}</h3><p>{scene.clue}</p><div className="fact-card"><Leaf size={18}/><span><b>红山资料里的真实线索</b><small>{scene.fact}</small></span></div><div className="story-next"><span>下一章 · 还差 2 个线索</span><button onClick={()=>go('tour')}>沿路线继续 <ArrowRight size={16}/></button></div></div>}<div className="story-v2-footer"><button className="primary full" disabled={!mode} onClick={()=>go('tour')}>{mode?`带着${a.name}去找下一条线索`:'先选择一种观察方式'} <ArrowRight size={17}/></button><button className="text-btn" onClick={()=>go('route')}>暂时跳过故事，查看普通路线</button></div></div>}
function CompanionStoryV3({s,go}:{s:State;go:(p:Page)=>void}){const a=animals[s.companion]||animals[0];const [chapter,setChapter]=useState(0);const [mode,setMode]=useState<'quiet'|'clue'|null>(null);const data=a.species==='貉'?{place:'本土物种保育区 · 荒丘野地',hook:'落叶堆里，少了一颗种子。',mid:'黄昏时，貉小满回到了那片落叶堆。',fact:'貉会把食物藏起来，忘记取回的种子可能在土里长成小树。',end:'你没有追上它，却在落叶下发现了一株刚冒头的小树。原来，消失的种子正在替森林留下下一季。'}:a.species==='赤狐'?{place:'本土物种保育区 · 山林边缘',hook:'那道红色身影，为什么停在距离你三步远的地方？',mid:'麦穗没有靠近，它在等你把安静还给它。',fact:'救助后的赤狐仍然需要保有野生动物的边界。保护不是驯服，而是尊重。',end:'你站在原地，麦穗转身跑进林缘。你们没有触碰彼此，却都拥有了自己的自由。'}:a.species==='獐'?{place:'本土物种保育区 · 一个池塘',hook:'池塘里没有人投喂，却一直保持着自己的秩序。',mid:'獐灯让你看见水面下的关系：鱼、虾、螺和植物，谁也不是配角。',fact:'植物、虾螺、小鱼和肥料循环共同维持池塘生态，形成不依赖人工投喂的自循环。',end:'你终于明白，森林的故事不是谁最耀眼，而是谁愿意把自己的位置让给别人。'}:{place:'熊猫馆 · 室外活动场',hook:'平平、和和、九九，为什么没有住在一起？',mid:'团团让你先看天气，再看场馆：动物会自己选择舒服的地方。',fact:'熊猫馆依据大熊猫的自然习性设置室内外空间，并尊重其独居和领地需求。',end:'你没有等到它们一直面对游客的画面，却看见了更重要的事：它们可以按自己的节奏生活。'};const next=()=>setChapter(v=>Math.min(2,v+1));return <div className="page story-page story-full"><div className="story-full-head"><p className="eyebrow">{a.name} 的今日故事</p><div className="story-chapter-count"><span className={chapter>=0?'on':''}/><span className={chapter>=1?'on':''}/><span className={chapter>=2?'on':''}/><b>第 {chapter+1} / 3 章</b></div></div>{chapter===0&&<><div className="story-full-hero"><Companion3D size="normal"/><p className="eyebrow">第一章 · 一封没有署名的信</p><h1>{data.hook}</h1><p>{data.place}</p></div><div className="story-letter"><span className="letter-mark">“</span><p>如果你愿意慢一点，沿着落叶、风和脚印走。<br/>你会发现，森林从来没有把故事藏起来，<br/>只是没有把它写在玻璃上。</p><small>—— {a.name} 留给你的线索</small></div><div className="story-choice"><p className="eyebrow">你准备怎么回应这封信？</p><button className={mode==='quiet'?'chosen':''} onClick={()=>setMode('quiet')}><span>A</span><div><b>安静等一等</b><small>把主动权交还给动物</small></div><ChevronRight size={17}/></button><button className={mode==='clue'?'chosen':''} onClick={()=>setMode('clue')}><span>B</span><div><b>沿着线索走</b><small>看看这片生境藏着什么</small></div><ChevronRight size={17}/></button></div><button className="primary full" disabled={!mode} onClick={next}>{mode?'进入第二章':'先选择你的回应'} <ArrowRight size={17}/></button></>}{chapter===1&&<><div className="story-full-hero mid"><div className="chapter-no">02</div><p className="eyebrow">第二章 · 你开始听见它</p><h1>{data.mid}</h1><p>{a.name} 的线索没有把你带向表演，而是带向一段关系。</p></div><div className="story-scene"><div className="scene-line"><span>09:18</span><i/><b>你在 {data.place} 停下</b></div><div className="scene-line"><span>09:24</span><i/><b>你发现一个不必靠近的观察位</b></div><div className="scene-line"><span>09:31</span><i/><b>{a.name} 终于留下自己的回应</b></div></div><div className="fact-card large"><Leaf size={20}/><span><b>这不是编出来的魔法</b><small>{data.fact}</small></span></div><button className="primary full" onClick={next}>进入终章，看看故事留下了什么 <ArrowRight size={17}/></button><button className="text-btn" onClick={()=>setChapter(0)}>回到第一章</button></>}{chapter===2&&<><div className="story-full-hero ending"><div className="chapter-no">03</div><p className="eyebrow">终章 · 把答案留在森林里</p><h1>{data.end}</h1><p>你今天不需要看完所有动物，也不需要把故事带走。</p></div><div className="ending-card"><div className="ending-quote">“</div><h2>{a.name} 的搭子守则</h2><p>不追逐 · 不投喂 · 不敲玻璃<br/>先观察，再理解；先尊重，再靠近。</p><div className="ending-score"><span>故事完成度</span><b>100%</b><i/></div></div><div className="story-route-link"><BookOpen size={18}/><div><b>故事与路线已对上</b><small>下一站：{s.active<2?'亚洲灵长馆':'本土动物区'} · 预计停留 20 分钟</small></div><ChevronRight size={17}/></div><button className="primary full" onClick={()=>go('tour')}>带着 {a.name} 出发 <ArrowRight size={17}/></button><button className="secondary full" onClick={()=>go('route')}>先查看完整路线</button><button className="text-btn" onClick={()=>setChapter(1)}>回看第二章</button></>}</div>}
function StoryGeneratorPage({s,go}:{s:State;go:(p:Page)=>void}){const animal=animals[s.companion]||animals[0];const [mode,setMode]=useState<StoryMode>('detective');const [story,setStory]=useState<GeneratedStory>(()=>generateStory(animal,s.routeMode,'detective'));const [open,setOpen]=useState(0);const rebuild=(m:StoryMode)=>{setMode(m);setOpen(0);setStory(generateStory(animal,s.routeMode,m))};return <div className="page generated-story"><div className="generated-head"><p className="eyebrow">STORY AGENT · 已结合你的路线</p><h1>把今天的路线，<br/>变成一场故事</h1><p>你的搭子会根据路线节点，为你生成一条只属于今天的任务。</p></div><div className="story-input-summary"><div className="story-mini-mascot"><Companion3D size="tiny"/></div><div><b>{animal.name} × {s.routeMode}</b><small>5 个路线节点 · 约 2 小时 · {animal.species}观察线索</small></div><button className="icon-btn" onClick={()=>rebuild(mode)}><RotateCcw size={16}/></button></div><p className="eyebrow mode-label">选择今天的故事口味</p><div className="mode-tabs">{([['detective','侦探故事','找出隐藏线索'],['forest','森林秘境','跟着自然走'],['letter','动物来信','听搭子说话']] as [StoryMode,string,string][]).map(([m,label,sub])=><button className={mode===m?'active':''} key={m} onClick={()=>rebuild(m)}><b>{label}</b><small>{sub}</small></button>)}</div><div className="generated-cover"><span className="case-number">CASE 0{mode==='detective'?'7':mode==='forest'?'3':'1'}</span><p className="eyebrow">{story.modeLabel}</p><h2>{story.title}</h2><p>{story.hook}</p><div className="cover-meta"><span>路线驱动</span><span>动物搭子：{animal.name}</span><span>随机生成</span></div></div><div className="story-timeline"><div className="timeline-title"><span>沿路线解锁故事</span><b>{open+1} / {story.chapters.length}</b></div>{story.chapters.map((ch,i)=><div className={`generated-chapter ${i===open?'open':''} ${i<open?'done':''}`} key={`${ch.point}-${i}`}><button onClick={()=>setOpen(i)}><span className="timeline-index">{i<open?'✓':`0${i+1}`}</span><span><b>{ch.point}</b><small>{ch.label} · {i===0?'入口':`${i*18+12} 分钟后`}</small></span><ChevronRight size={17}/></button>{i===open&&<div className="chapter-detail"><p>{ch.text}</p><div className="mission"><Sparkles size={15}/><span><b>到达这里时做一件事</b><small>{ch.action}，不要敲玻璃、投喂或追逐。</small></span></div>{i<story.chapters.length-1?<button className="next-chapter" onClick={()=>setOpen(i+1)}>我找到线索了，继续 <ArrowRight size={15}/></button>:<div className="final-note">最后一站会告诉你，为什么红山的故事不需要表演。</div>}</div>}</div>)}</div><div className="generated-ending"><Leaf size={19}/><p>{story.ending}</p></div><button className="primary full" onClick={()=>go('tour')}>带着这条故事出发 <ArrowRight size={17}/></button><button className="secondary full" onClick={()=>rebuild(mode)}>再生成一条不同故事 <RotateCcw size={16}/></button></div>}
function TourV2({s,setS,go}:{s:State;setS:React.Dispatch<React.SetStateAction<State>>;go:(p:Page)=>void}){const p=points[s.active];const a=animals[s.companion]||animals[0];return <div className="page tour-page"><div className="tour-status"><div><p className="eyebrow">{s.routeMode} · {s.active+1}/5</p><h2>正在前往 {p.name}</h2></div><div className="time"><b>{s.active===0?'1h52':'1h18'}</b><small>剩余时间</small></div></div><div className="tour-alert"><Bell size={17}/><span><b>抵达后会触发 {p.name} 讲解</b><small>{p.sub} · 搭子 {a.name} 正在整理线索</small></span><ChevronRight size={17}/></div><div className="tour-map"><MapArt active={s.active}/><div className="location">当前位置 · 路线节点 {s.active+1}</div></div><div className="now-card"><div className="now-icon"><Leaf/></div><div><p className="eyebrow">下一站</p><h3>{p.name}</h3><p>距离 380m · 预计 8 分钟</p></div><button className="icon-btn"><Volume2 size={18}/></button></div><div className="companion-line"><Companion3D size="tiny"/><p>“到这里以后，先听我讲一小段，再一起看看。”</p></div><div className="quick-actions"><button onClick={()=>go('ask')}><Mic/><span>问搭子</span></button><button onClick={()=>go('venue')}><BookOpen/><span>提前听讲解</span></button><button onClick={()=>setS(v=>({...v,adjustment:'已插入休息区',page:'tour'}))}><Leaf/><span>我累了</span></button><button onClick={()=>go('ask')}><CircleHelp/><span>其他问题</span></button></div><button className="primary full" onClick={()=>go('venue')}>到达 {p.name}，开始讲解 <ArrowRight size={17}/></button></div>}
function VenueV2({s,setS,go}:{s:State;setS:React.Dispatch<React.SetStateAction<State>>;go:(p:Page)=>void}){const p=points[s.active];const a=animals[s.companion]||animals[0];const [q,setQ]=useState('');const [answer,setAnswer]=useState('');const [listening,setListening]=useState(false);const ask=()=>{if(!q.trim())return;const r=answerFromKnowledge(`${p.name} ${q}`);setAnswer(r.answer);if(typeof window!=='undefined'&&'speechSynthesis' in window)window.speechSynthesis.speak(new SpeechSynthesisUtterance(r.answer));};const listen=()=>{const w=window as Window&{webkitSpeechRecognition?:new()=>{lang:string;start:()=>void;onresult:(e:{results:ArrayLike<ArrayLike<{transcript:string}>>})=>void;onend:()=>void}};if(!w.webkitSpeechRecognition){setListening(true);setTimeout(()=>setListening(false),1200);return}const rec=new w.webkitSpeechRecognition();rec.lang=localStorage.getItem('hs-language')||'zh-CN';setListening(true);rec.onresult=e=>{const text=e.results[0][0].transcript;setQ(text);setListening(false)};rec.onend=()=>setListening(false);rec.start()};const next=()=>{if(s.active>=4)go('complete');else setS(v=>({...v,active:v.active+1,page:'tour'}))};return <div className="page venue-live"><button className="language-pill" onClick={()=>{const next=localStorage.getItem('hs-language')==='en'?'zh-CN':'en';localStorage.setItem('hs-language',next);location.reload()}}>{localStorage.getItem('hs-language')==='en'?'EN':'中'} · language</button><div className="venue-hero"><div className="venue-symbol"><Leaf/></div><p className="eyebrow">已到达路线节点 {s.active+1}/5 · {p.name}</p><h1>{p.name}</h1><div className="active-chip"><i/> {a.name} 已为你准备好这一站</div></div><div className="live-guide"><div className="guide-top"><Companion3D size="tiny"/><div><b>{a.name} 的现场讲解</b><small>亲子故事版 · 约 2 分钟</small></div><button className="play" onClick={()=>{if('speechSynthesis' in window)window.speechSynthesis.speak(new SpeechSynthesisUtterance(`${p.name}。${p.sub}。请先安静观察，不要敲击玻璃或投喂。`))}}><Play fill="currentColor" size={15}/></button></div><p>{a.name} 说：先别急着寻找它们。站在这里听一会儿，{p.sub}。动物不需要随时出现在游客面前，给它们保留自己的节奏，就是最好的见面。</p><div className="audio-line"><i/></div></div><div className="ask-companion"><div className="ask-companion-head"><Sparkles size={16}/><b>想问搭子什么？</b><span>支持语音 / 文字</span></div><div className="voice-row"><button className={`voice-btn ${listening?'listening':''}`} onClick={listen}><Mic size={20}/></button><input value={q} onChange={e=>setQ(e.target.value)} onKeyDown={e=>e.key==='Enter'&&ask()} placeholder={listening?'正在听你说…':'问问这一站的动物、场馆或故事'}/><button className="send-btn" onClick={ask}><ArrowRight size={17}/></button></div>{answer&&<div className="companion-answer"><Companion3D size="tiny"/><div><b>{a.name} 回答你</b><p>{answer}</p><small>基于红山本地知识库 · 当前场馆上下文</small></div></div>}<div className="question-chips">{['为什么不能敲玻璃？','它现在可能在做什么？','这里和自然有什么关系？'].map(x=><button key={x} onClick={()=>{setQ(x);setTimeout(ask,0)}}>{x}</button>)}</div></div><div className="observe"><Leaf size={18}/><span><b>不打扰地观察</b><small>不敲玻璃 · 不投喂 · 不使用强闪光 · 动物休息时请耐心等待</small></span></div><button className="primary full" onClick={next}>{s.active>=4?'完成游览':'继续下一站'} <ArrowRight size={17}/></button></div>}
function VenueV3({s,setS,go}:{s:State;setS:React.Dispatch<React.SetStateAction<State>>;go:(p:Page)=>void}){const mission=nodeMissions[s.active]||nodeMissions[0];const done=s.npcTasks.includes(s.active);const clue=s.clues.includes(mission.clue);const [response,setResponse]=useState('');const [showTask,setShowTask]=useState(false);const [saved,setSaved]=useState(false);const completeTask=()=>{if(done)return;setS(v=>({...v,npcTasks:[...v.npcTasks,s.active],stamps:[...v.stamps,mission.npc],score:v.score+30,clues:clue?v.clues:[...v.clues,mission.clue]}));setSaved(true);setShowTask(false)};const next=()=>{if(s.active>=4)go('complete');else setS(v=>({...v,active:v.active+1,page:'tour'}))};return <div className="page node-page"><div className="node-hero"><div className="node-stamp">{done?'✓':`0${s.active+1}`}</div><p className="eyebrow">到达节点 {s.active+1}/5 · {points[s.active].name}</p><h1>{points[s.active].name}</h1><p>{points[s.active].sub}</p></div><div className="node-story"><div className="story-label"><BookOpen size={15}/> 故事指引</div><h2>{mission.story}</h2><p>{s.companion===1?'貉小满在落叶边缘停下来，像是在等一个懂得观察的人。':`你的搭子${animals[s.companion]?.name||'团团'}把线索放在这里：先别急着走，故事还差一小段。`}</p><div className="node-reminder"><Bell size={15}/><span>到达这里后，先收集线索，再去找线下 NPC。</span></div></div><div className={`clue-card ${clue?'collected':''}`}><div className="clue-icon">{clue?'✓':'?'}</div><div><p className="eyebrow">路线线索 {clue?'已收集':'待发现'}</p><h3>{mission.clue}</h3><p>{clue?'已加入你的故事线索册':'在附近观察 30 秒，找到它并点击收集。'}</p></div>{!clue&&<button onClick={()=>setS(v=>({...v,clues:[...v.clues,mission.clue]}))}>收集</button>}</div><div className="npc-card"><div className="npc-avatar">{done?'✓':'NPC'}</div><div className="npc-copy"><span className="npc-status">{done?'互动已完成 · 已盖章':'线下 NPC 互动点'}</span><h2>{mission.npc}</h2><p>{mission.task} · 预计 2 分钟</p></div><span className="offline-tag">线下</span></div>{!done&&!showTask&&<button className="primary full" onClick={()=>setShowTask(true)}>和 {mission.npc} 完成任务 <Sparkles size={17}/></button>}{showTask&&!done&&<div className="npc-task"><p className="eyebrow">NPC 出题 · {mission.task}</p><h3>{mission.prompt}</h3><div className="task-answer"><input value={response} onChange={e=>setResponse(e.target.value)} placeholder="输入你的回答，或告诉 NPC 你的选择"/><button onClick={completeTask}>提交</button></div><small>演示模式：回答任意内容即可完成线下互动。</small></div>}{(done||saved)&&<div className="stamp-success"><div className="stamp-ink">印</div><div><b>{mission.npc} 已为你盖章</b><p>获得 +30 成长值 · 线索已加入故事线</p></div></div>}<div className="value-note"><Leaf size={17}/><span><b>红山观察公约</b><small>不敲玻璃、不投喂、不追逐。完成任务的方式不是打扰动物，而是和 NPC 一起理解它们。</small></span></div><button className="primary full" disabled={!done} onClick={next}>{s.active>=4?'完成故事线':'继续下一节点'} <ArrowRight size={17}/></button></div>}

function VenueV4({s,setS,go}:{s:State;setS:React.Dispatch<React.SetStateAction<State>>;go:(p:Page)=>void}){const p=points[s.active];const a=animals[s.companion]||animals[0];const [q,setQ]=useState('');const [answer,setAnswer]=useState('');const [busy,setBusy]=useState(false);const [listening,setListening]=useState(false);const guideText=`${a.name}：先别急着寻找它们。站在这里听一会儿，${p.sub}。给动物保留自己的节奏，就是最好的见面。`;const ask=async(text=q)=>{if(!text.trim())return;setBusy(true);try{const r=await askCompanion({question:text,context:`当前景点：${p.name}。官方提示：${p.sub}`,companion:a.name});setAnswer(r.answer)}catch{setAnswer(answerFromKnowledge(`${p.name} ${text}`).answer)}finally{setBusy(false)}};const speak=async()=>{const text=answer||guideText;try{const r=await synthesizeSpeech(text);if(r.enabled&&r.audio_base64){const audio=new Audio(`data:${r.mime_type||'audio/mpeg'};base64,${r.audio_base64}`);await audio.play();return}}catch{}if('speechSynthesis'in window)window.speechSynthesis.speak(new SpeechSynthesisUtterance(text))};const listen=()=>{const w=window as Window&{webkitSpeechRecognition?:new()=>any};if(!w.webkitSpeechRecognition){setListening(true);setTimeout(()=>setListening(false),1200);return}const rec=new w.webkitSpeechRecognition();rec.lang=localStorage.getItem('hs-language')||'zh-CN';setListening(true);rec.onresult=(e:any)=>{const text=e.results[0][0].transcript;setQ(text);setListening(false);ask(text)};rec.onend=()=>setListening(false);rec.start()};const next=()=>{if(s.active>=4)go('complete');else setS(v=>({...v,active:v.active+1,page:'tour'}))};return <div className="page venue-live"><button className="language-pill" onClick={()=>{const next=localStorage.getItem('hs-language')==='en'?'zh-CN':'en';localStorage.setItem('hs-language',next);location.reload()}}>{localStorage.getItem('hs-language')==='en'?'EN':'中'} · language</button><div className="venue-hero"><div className="venue-symbol"><Leaf/></div><p className="eyebrow">已到达路线节点 {s.active+1}/5 · {p.name}</p><h1>{p.name}</h1><div className="active-chip"><i/> {a.name} 已为你准备好这一站</div></div><div className="live-guide"><div className="guide-top"><Companion3D size="tiny"/><div><b>{a.name} 的现场讲解</b><small>由百炼 CosyVoice 朗读 · 约 2 分钟</small></div><button className="play" onClick={speak}><Play fill="currentColor" size={15}/></button></div><p>{guideText}</p><div className="audio-line"><i/></div></div><div className="ask-companion"><div className="ask-companion-head"><Sparkles size={16}/><b>想问搭子什么？</b><span>语音 / 文字 · 百炼 Qwen</span></div><div className="voice-row"><button className={`voice-btn ${listening?'listening':''}`} onClick={listen}><Mic size={20}/></button><input value={q} onChange={e=>setQ(e.target.value)} onKeyDown={e=>e.key==='Enter'&&ask()} placeholder={listening?'正在听你说…':'问问这一站的动物、场馆或故事'}/><button className="send-btn" onClick={()=>ask()}><ArrowRight size={17}/></button></div>{answer&&<div className="companion-answer"><Companion3D size="tiny"/><div><b>{a.name} 回答你</b><p>{busy?'正在查找红山知识…':answer}</p><button className="secondary" onClick={speak}>朗读回答</button><small>回答由百炼生成，事实以园区现场公告为准</small></div></div>}<div className="question-chips">{['为什么不能敲玻璃？','它现在可能在做什么？','这里和自然有什么关系？'].map(x=><button key={x} onClick={()=>{setQ(x);ask(x)}}>{x}</button>)}</div></div><div className="observe"><Leaf size={18}/><span><b>不打扰地观察</b><small>不敲玻璃 · 不投喂 · 不使用强闪光 · 动物休息时请耐心等待</small></span></div><button className="primary full" onClick={next}>{s.active>=4?'完成游览':'继续下一站'} <ArrowRight size={17}/></button></div>}

function AskV2({go}:{go:(p:Page)=>void}){const [q,setQ]=useState('');const [answer,setAnswer]=useState('');const [source,setSource]=useState('');const [busy,setBusy]=useState(false);const ask=async(text=q)=>{if(!text.trim())return;setBusy(true);try{const r=await askCompanion({question:text,context:'红山动物园全园问答',companion:'小红'});setAnswer(r.answer);setSource(r.source)}catch{const r=answerFromKnowledge(text);setAnswer(r.answer);setSource(r.sources.length?'local_knowledge':'fallback')}finally{setBusy(false)}};return <div className="page ask-page"><p className="eyebrow">BAILIAN RAG · 红山知识库</p><h1>问问红山</h1><p className="ask-lead">关于动物、场馆、保育和文明观察，可以直接语音或文字询问。</p><div className="ask-input"><input value={q} onChange={e=>setQ(e.target.value)} onKeyDown={e=>e.key==='Enter'&&ask()} placeholder="例如：貉什么时候更活跃？"/><button onClick={()=>ask()}><ArrowRight size={18}/></button></div><div className="suggestions">{['貉什么时候更活跃？','为什么不能敲玻璃？','一个池塘是怎么自循环的？'].map(x=><button key={x} onClick={()=>{setQ(x);ask(x)}}>{x}</button>)}</div>{answer&&<div className="rag-result"><div className="rag-badge"><BookOpen size={15}/> {source==='bailian'?'已由百炼知识问答生成':'本地知识兜底回答'}</div><p>{busy?'正在检索红山知识库…':answer}</p></div>}<button className="secondary full ask-back" onClick={()=>go('home')}>回到首页</button></div>}
function GrowthV3({s,go}:{s:State;go:(p:Page)=>void}){const level=s.score>=120?'森林守护者':s.score>=60?'线索收集员':'初来访客';return <div className="page growth-v3"><div className="growth-v3-head"><Companion3D size="normal"/><div><p className="eyebrow">我的故事印记</p><h1>{animals[s.companion]?.name||'团团'}</h1><p>{level} · {s.score} 成长值</p></div></div><div className="value-level"><div><b>成长等级 · {Math.floor(s.score/60)+1}</b><span>{s.score} / 180</span></div><div className="level-line"><i style={{width:`${Math.min(100,s.score/1.8)}%`}}/></div><small>每完成一个线下 NPC 任务，获得 30 成长值和一枚节点印章。</small></div><div className="growth-v3-stats"><span><b>{s.clues.length}</b>线索</span><span><b>{s.npcTasks.length}</b>NPC 任务</span><span><b>{s.stamps.length}</b>节点印章</span></div><section className="stamp-book"><div className="section-head"><h3>故事印记册</h3><span>{s.stamps.length}/5</span></div><div className="stamp-grid">{nodeMissions.map((m,i)=><div className={s.npcTasks.includes(i)?'earned':''} key={m.npc}><span>{s.npcTasks.includes(i)?'印':`0${i+1}`}</span><small>{m.npc}</small></div>)}</div></section><section className="reward-section"><div className="section-head"><h3>成长兑换</h3><span>Mock 兑换</span></div>{rewards.map(r=><div className="reward-row" key={r.id}><div className="reward-icon">♧</div><div><b>{r.name}</b><small>{r.desc}</small></div><button disabled={s.score<r.cost||s.redeemed.includes(r.id)} onClick={()=>{setS(v=>({...v,score:v.score-r.cost,redeemed:[...v.redeemed,r.id]}));}}>{s.redeemed.includes(r.id)?'已兑换':s.score>=r.cost?'兑换':`${r.cost}分`}</button></div>)}</section><p className="reward-note"><Leaf size={14}/> 兑换是原型演示，实际纪念品、库存和核销规则由园区运营端配置。</p><button className="secondary full" onClick={()=>go('home')}>回到首页</button></div>}
function HomePageV2({s,go}:{s:State;go:(p:Page)=>void}){const a=animals[s.companion]||animals[0];return <div className="page home-map-first"><div className="home-map-head"><div><p className="eyebrow">2026年7月28日 · 周二</p><h1>下午好，{a.name}的伙伴</h1><p>今天先看看红山，再决定从哪一站开始。</p></div><div className="sun">☼</div></div><div className="live-weather"><span>☀ 29°</span><span>树荫舒适</span><span>客流较低</span><b>模拟实时</b></div><section className="home-map-card"><div className="map-card-top"><div><p className="eyebrow">TODAY AT HONGSHAN</p><h2>今天的红山</h2></div><span className="map-badge"><i/>推荐路线</span></div><div className="home-map-wrap"><MapArt active={s.active}/><div className="map-overlay-label"><Map size={13}/> 园区导览示意图</div><div className="map-current"><span/>当前位置 · 园区入口</div></div><div className="map-legend"><span><i className="legend-route"/>轻松亲子线</span><span><i className="legend-point"/>故事节点 5</span><span><i className="legend-shade"/>树荫覆盖 72%</span></div><button className="primary full" onClick={()=>go('plan')}>从地图开始规划 <ArrowRight size={17}/></button></section><div className="home-route-callout"><Companion3D size="tiny"/><div><p className="eyebrow">{a.name} 的推荐</p><b>先去本土物种保育区，那里有一条线索在等你。</b><small>2 小时 · 3.2km · 低拥挤</small></div><ChevronRight size={17}/></div><div className="section-head"><h3>今天的动物动态</h3><span>模拟实时数据</span></div><div className="animal-row">{animals.slice(0,2).map(x=><div className="animal-card" key={x.name}><div className="animal-avatar" style={{background:x.color}}>{x.name===a.name?<Companion3D size="tiny"/>:x.emoji}</div><div><b>{x.name}</b><p>{x.active}</p></div><span className="dot"/></div>)}</div><div className="story-mini" onClick={()=>go('story')}><div><p className="eyebrow">路线故事已生成</p><h3>带着 {a.name} 去找一条线索</h3><p>抵达节点后，线下 NPC 会等你完成任务。</p></div><BookOpen size={24}/></div></div>}
function PlanV2({s,setS}:{s:State;setS:React.Dispatch<React.SetStateAction<State>>}){const [input,setInput]=useState(s.preference||'');const [detected,setDetected]=useState('');const detect=(text:string)=>{setInput(text);setDetected(text.includes('熊猫')?'已识别：熊猫馆是今天的必去目标':text.includes('休息')||text.includes('累')?'已识别：需要安排更多休息节点':text?'已识别：会根据这句话调整路线重点':'')};const generate=()=>setS(v=>({...v,page:'route',preference:input||'希望轻松游览，优先树荫和动物故事'}));return <div className="page plan-natural"><div className="natural-head"><p className="eyebrow">ROUTE AGENT · NATURAL INPUT</p><h1>告诉我，今天最想去哪？</h1><p>不需要填写复杂筛选，像和搭子聊天一样说就好。</p></div><div className="natural-chat"><Companion3D size="tiny"/><div><b>我会记住你的必去目标</b><small>也会帮你补上时间、体力和故事节点。</small></div></div><div className="natural-input-card"><textarea value={input} onChange={e=>detect(e.target.value)} placeholder="例如：我今天就是很想去熊猫馆，最好能在树荫下慢慢逛，不想走太累。"/><div className="input-tools"><button onClick={()=>detect('我今天就是很想去熊猫馆，想轻松一点。')}><Mic size={16}/>语音输入</button><span>{input.length}/120</span></div></div>{detected&&<div className="detected-preference"><Sparkles size={16}/><span>{detected}<small>会在路线结果中说明它如何影响推荐</small></span></div>}<p className="eyebrow">也可以从这里开始</p><div className="preference-chips"><button onClick={()=>detect('我今天就是很想去熊猫馆。')}>🐼 今天很想去熊猫馆</button><button onClick={()=>detect('我想看动物，但不想爬山。')}>不想爬山</button><button onClick={()=>detect('我带着孩子，需要一个休息点。')}>带孩子，需要休息</button></div><div className="natural-summary"><div><span>已知条件</span><b>2 小时 · 轻松 · {s.preference?'已加入个性偏好':'等待你的偏好'}</b></div><ChevronRight size={17}/></div><button className="primary full" onClick={generate}>把我的偏好放进路线 <Sparkles size={17}/></button><p className="privacy"><Leaf size={13}/> 偏好只用于本次路线生成，可随时修改</p></div>}
function RoutePageV2({s,setS,go}:{s:State;setS:React.Dispatch<React.SetStateAction<State>>;go:(p:Page)=>void}){return <div className="route-v2-wrap">{s.preference&&<div className="preference-impact"><Sparkles size={16}/><div><b>已把你的偏好放进路线</b><small>“{s.preference}”</small></div><span>熊猫馆优先 · 已保留</span></div>}<RoutePage s={s} setS={setS} go={go}/></div>}
function PlanV3({s,setS}:{s:State;setS:React.Dispatch<React.SetStateAction<State>>}){const [input,setInput]=useState(s.preference||'');const [editing,setEditing]=useState(false);const [detected,setDetected]=useState(Boolean(s.preference));const detect=(text:string)=>{setInput(text);setDetected(Boolean(text.trim()))};const generate=()=>setS(v=>({...v,page:'route',preference:input||'希望轻松游览，优先树荫和动物故事'}));const known=[['可用时间','2 小时'],['同行伙伴','带着 3 岁孩子'],['体力状态','轻松'],['特别在意','怕晒 · 中途休息'],['动物偏好','灵长类']];return <div className="page plan-merged"><div className="merged-head"><p className="eyebrow">ROUTE AGENT · 和你的搭子一起规划</p><h1>今天，想怎么逛红山？</h1><p>我已经记住你的游玩条件，再告诉我今天最想去哪里。</p></div><div className="known-card"><div className="known-card-head"><div><span className="memory-dot"/><b>我已经知道这些</b></div><button onClick={()=>setEditing(!editing)}>{editing?'收起':'修改'}</button></div><div className="known-grid">{known.map(([a,b])=><div key={a}><small>{a}</small><b>{b}</b></div>)}</div><p className="known-note"><Leaf size={14}/> 这些信息会和“今天最想去哪里”一起影响路线，不是两套表单。</p></div><div className="merged-divider"><span>今天新增一个愿望</span></div><div className="wish-chat"><Companion3D size="tiny"/><div><b>告诉我今天最想去哪里</b><small>可以说一个场馆，也可以说一种心情。</small></div></div><div className="wish-input"><textarea value={input} onChange={e=>detect(e.target.value)} placeholder="例如：我今天就是很想去熊猫馆，最好能在树荫下慢慢逛。"/><div><button onClick={()=>detect('我今天就是很想去熊猫馆，想轻松一点。')}><Mic size={16}/>语音输入</button><span>{input.length}/120</span></div></div>{detected&&<div className="preference-readback"><Sparkles size={16}/><div><b>我听见了：{input.includes('熊猫')?'熊猫馆是今天的必去目标':'你有一个今天特别想实现的愿望'}</b><small>我会保留这个目标，再为你安排不晒、少走和有故事的路径。</small></div></div>}<p className="eyebrow">你也可以直接点选</p><div className="preference-chips"><button onClick={()=>detect('我今天就是很想去熊猫馆。')}>🐼 今天很想去熊猫馆</button><button onClick={()=>detect('我想看动物，但不想爬山。')}>不想爬山</button><button onClick={()=>detect('我带着孩子，需要一个休息点。')}>带孩子，需要休息</button></div><button className="primary full" onClick={generate}>让搭子把这些合成一条路线 <Sparkles size={17}/></button><p className="privacy"><Leaf size={13}/> 你可以随时回到这里修改条件或愿望</p></div>}
function PlanV4({s,setS}:{s:State;setS:React.Dispatch<React.SetStateAction<State>>}){const [input,setInput]=useState(s.preference||'');const [values,setValues]=useState<Record<string,string>>({time:'',company:'',energy:'',shade:'',rest:''});const [field,setField]=useState<string|null>(null);const choices:Record<string,string[]|undefined>={time:['1 小时','2 小时','半天','全天'],company:['自己','和朋友','带着孩子'],energy:['轻松','适中','想挑战'],shade:['不介意','比较怕晒'],rest:['不需要','需要休息点']};const setValue=(key:string,value:string)=>{setValues(v=>({...v,[key]:value}));setField(null)};const filled=Object.values(values).filter(Boolean).length;const generate=()=>{const summary=Object.entries(values).filter(([,v])=>v).map(([k,v])=>`${k}:${v}`).join(' · ');setS(v=>({...v,page:'route',preference:[input||'今天没有额外目标',summary].filter(Boolean).join(' · ')}))};return <div className="page plan-form"><div className="form-head"><p className="eyebrow">ROUTE AGENT · 先了解你的今天</p><h1>和搭子一起，<br/>定制今天的红山</h1><p>没有预设答案，先告诉我你的真实情况。</p></div><section className="form-section"><div className="form-section-title"><span>01</span><div><b>先告诉我这些</b><small>可选填，没想好也可以跳过</small></div></div><div className="form-fields">{[['time','可以逛多久？'],['company','今天和谁一起？'],['energy','今天的体力？'],['shade','怕晒吗？'],['rest','需要休息点吗？']].map(([key,label])=><div key={key}><button className={values[key]?'form-field filled':'form-field'} onClick={()=>setField(field===key?null:key)}><span>{label}</span><b>{values[key]||'请选择'}</b><ChevronRight size={15}/></button>{field===key&&<div className="inline-options">{choices[key]?.map(x=><button key={x} onClick={()=>setValue(key,x)}>{x}</button>)}</div>}</div>)}</div><div className="filled-count">已填写 {filled}/5 项 · 你可以随时修改</div></section><div className="form-divider"><span>02 · 再告诉我今天最想去哪里</span></div><section className="wish-section"><div className="wish-chat"><Companion3D size="tiny"/><div><b>今天有没有一个特别想去的地方？</b><small>说场馆、动物，或者一种心情都可以。</small></div></div><div className="wish-input"><textarea value={input} onChange={e=>setInput(e.target.value)} placeholder="例如：今天就是很想去熊猫馆，最好能在树荫下慢慢逛。"/><div><button onClick={()=>setInput('今天就是很想去熊猫馆，想轻松一点。')}><Mic size={16}/>语音输入</button><span>{input.length}/120</span></div></div><div className="preference-chips"><button onClick={()=>setInput('今天就是很想去熊猫馆。')}>🐼 今天很想去熊猫馆</button><button onClick={()=>setInput('我不想爬山。')}>不想爬山</button><button onClick={()=>setInput('我带着孩子，需要休息点。')}>带孩子，需要休息</button></div></section><div className="form-preview"><Sparkles size={16}/><span><b>{filled||input?'我会把你的选择合成一条路线':'填写后这里会出现路线预览'}</b><small>{filled?`${filled} 个游玩条件已加入`:'路线会同时考虑时间、体力、同行人和必去目标'}</small></span></div><button className="primary full" onClick={generate}>生成我的专属路线 <ArrowRight size={17}/></button><p className="privacy"><Leaf size={13}/> 只有你主动填写的内容，才会进入路线规划</p></div>}
function PlanV5({s,setS}:{s:State;setS:React.Dispatch<React.SetStateAction<State>>}){const [text,setText]=useState('');const [loading,setLoading]=useState(false);const [status,setStatus]=useState('');const submit=async()=>{setLoading(true);setStatus('正在理解你的条件并计算路线…');try{const result=await planRoute({natural_language:text,preferences:{duration_minutes:120,pace:'slow',avoid_climbing:text.includes('爬山')||text.includes('累'),avoid_sun:text.includes('晒'),with_child:text.includes('孩子'),preferred_animals:text.includes('熊猫')?['大熊猫']:[],must_visit:text.includes('熊猫')?['panda']:[]}});setS(v=>({...v,page:'route',preference:text||'今天没有额外目标',routeMode:result.route.route_mode==='effort_saving'?'省力优先线':v.routeMode}));}catch{setStatus('路线服务暂不可用，已切换本地演示模式');setTimeout(()=>setS(v=>({...v,page:'route',preference:text||'今天没有额外目标'})),500)}finally{setLoading(false)}};return <div className="page plan-form"><div className="form-head"><p className="eyebrow">ROUTE AGENT · API CONNECTED</p><h1>今天想怎么逛红山？</h1><p>告诉我时间、同行人、体力，以及今天最想去的地方。</p></div><div className="api-chat"><Companion3D size="tiny"/><div><b>你的话会交给路线服务处理</b><small>自然语言 → 结构化需求 → 约束路线计算</small></div></div><div className="wish-input api-input"><textarea value={text} onChange={e=>setText(e.target.value)} placeholder="我带着孩子，只有 2 小时，怕晒，今天很想去熊猫馆。"/><div><button onClick={()=>setText('我带着孩子，只有 2 小时，怕晒，今天很想去熊猫馆。')}><Mic size={16}/>使用演示语句</button><span>{text.length}/160</span></div></div><div className="preference-chips"><button onClick={()=>setText('今天很想去熊猫馆')}>熊猫馆优先</button><button onClick={()=>setText('我不想爬山，想轻松一点')}>省力优先</button><button onClick={()=>setText('带孩子，需要中途休息')}>亲子休息</button></div><div className="api-steps"><span className="done">1 <b>理解需求</b></span><span>2 <b>计算路线</b></span><span>3 <b>解释推荐</b></span></div>{status&&<div className="api-status"><Sparkles size={15}/>{status}</div>}<button className="primary full" disabled={loading} onClick={submit}>{loading?'正在生成…':'生成我的专属路线'} <ArrowRight size={17}/></button><p className="privacy"><Leaf size={13}/> 后端 API 连接：{import.meta.env.VITE_API_BASE||'http://127.0.0.1:8000'}</p></div>}
function StoryGeneratorPageV2({s,go}:{s:State;go:(p:Page)=>void}){
  const animal=animals[s.companion]||animals[0]
  const [mode,setMode]=useState<StoryMode>('detective')
  const [story,setStory]=useState<GeneratedStory>(()=>generateStory(animal,s.routeMode,'detective'))
  const [open,setOpen]=useState(0)
  const rebuild=(next:StoryMode)=>{setMode(next);setOpen(0);setStory(generateStory(animal,s.routeMode,next))}
  return <div className="page generated-story"><div className="generated-head"><p className="eyebrow">STORY AGENT · 已结合你的路线</p><h1>选择今天的故事入口</h1><p>同一条路线，可以成为不同的冒险。你选择的模式会改变线索、NPC任务和结局。</p></div><div className="story-input-summary"><div className="story-mini-mascot"><Companion3D size="tiny"/></div><div><b>{animal.name} × {s.routeMode}</b><small>5 个路线节点 · {animal.species}观察线索</small></div><button className="icon-btn" onClick={()=>rebuild(mode)}><RotateCcw size={16}/></button></div><p className="eyebrow mode-label">选择故事风格</p><div className="mode-tabs mode-tabs-six">{storyModeOptions.map(x=><button className={mode===x.mode?'active':''} key={x.mode} onClick={()=>rebuild(x.mode)}><span className="mode-icon">{x.icon}</span><b>{x.label}</b><small>{x.sub}</small></button>)}</div><div className="generated-cover"><span className="case-number">STORY 0{storyModeOptions.findIndex(x=>x.mode===mode)+1}</span><p className="eyebrow">{story.modeLabel}</p><h2>{story.title}</h2><p>{story.hook}</p><div className="cover-meta"><span>路线驱动</span><span>动物搭子：{animal.name}</span><span>可与 NPC 互动</span></div></div><div className="story-timeline"><div className="timeline-title"><span>沿路线解锁故事</span><b>{open+1} / {story.chapters.length}</b></div>{story.chapters.map((ch,i)=><div className={`generated-chapter ${i===open?'open':''} ${i<open?'done':''}`} key={`${ch.point}-${i}`}><button onClick={()=>setOpen(i)}><span className="timeline-index">{i<open?'✓':`0${i+1}`}</span><span><b>{ch.point}</b><small>{ch.label} · {i===0?'入口':`${i*18+12} 分钟后`}</small></span><ChevronRight size={17}/></button>{i===open&&<div className="chapter-detail"><p>{ch.text}</p><div className="mission"><Sparkles size={15}/><span><b>到达这里时做一件事</b><small>{ch.action}，不要敲玻璃、投喂或追逐。</small></span></div>{i<story.chapters.length-1?<button className="next-chapter" onClick={()=>setOpen(i+1)}>我找到线索了，继续 <ArrowRight size={15}/></button>:<div className="final-note">最后一站会揭开这条故事真正想留下的东西。</div>}</div>}</div>)}</div><div className="generated-ending"><Leaf size={19}/><p>{story.ending}</p></div><button className="primary full" onClick={()=>go('tour')}>带着这条故事出发 <ArrowRight size={17}/></button><button className="secondary full" onClick={()=>rebuild(mode)}>再生成一条不同故事 <RotateCcw size={16}/></button></div>
}

;(StoryGeneratorPage as any) = StoryGeneratorPageV2

function ShellV2({s,children}:{s:State;children:React.ReactNode}){return <div className="app"><header className="topbar"><button className="icon-btn" onClick={()=>latestBack()}><ArrowLeft size={18}/></button><span className="top-title">{s.page==='growth'?'我的游伴':s.page==='tour'?'正在游览':s.page==='venue'?'到达场馆':s.page==='route'?'今日路线':'山野游伴'}</span><button className="icon-btn"><Menu size={19}/></button></header><main>{children}</main>{!['tour','venue','complete','route','story','plan'].includes(s.page)&&<nav><button className={s.page==='home'?'on':''} onClick={()=>latestGo('home')}><Home/><span>首页</span></button><button className={s.page==='plan'?'on':''} onClick={()=>latestGo('plan')}><Map/><span>行程</span></button><button className={s.page==='growth'?'on':''} onClick={()=>latestGo('growth')}><Compass/><span>游伴</span></button><button className={s.page==='growth'?'on':''} onClick={()=>latestGo('growth')}><CircleHelp/><span>我的</span></button></nav>}</div>}
;(Shell as any)=ShellV2

function RoutePageV3({s,go}:{s:State;go:(p:Page)=>void}){
  let result:any=null
  try{result=JSON.parse(localStorage.getItem('hs-last-route')||'null')}catch{}
  const route=result?.route
  const summary=route?.summary||{total_minutes:0,total_distance_m:0,walking_minutes:0,stay_minutes:0}
  const items=route?.ordered_pois||[]
  return <div className="route-v2-wrap"><div className="preference-impact"><Sparkles size={16}/><div><b>{result?.source==='qwen'?'百炼 Qwen 已解析需求':'路线服务已返回结果'}</b><small>{s.preference||'本次游玩偏好'}</small></div><span>{route?.planning_method||'等待路线数据'}</span></div><div className="page route-page"><div className="route-intro"><p className="eyebrow">ROUTE AGENT · {route?.data_source||'API RESULT'}</p><h1>{route?.route_mode==='effort_saving'?'省力优先线':route?.route_mode==='interest_first'?'动物探索线':'今日专属路线'}</h1><p>这条路线由当前需求和园区拓扑图实时计算，不再使用固定路线。</p></div><div className="route-summary"><span><b>{summary.total_minutes||'—'}m</b>预计耗时</span><span><b>{summary.total_distance_m?`${(summary.total_distance_m/1000).toFixed(1)}km`:'—'}</b>步行距离</span><span><b>{summary.walking_minutes||'—'}m</b>步行时间</span><span><b>{items.length||'—'}</b>个节点</span></div><div className="map-card"><MapArt active={s.active}/><div className="map-label">官方地图 · 拓扑规划路线</div></div><div className="why"><h3>为什么这样推荐？</h3><p>{(route?.reasons||['路线服务暂未返回解释']).join('；')}</p></div><div className="route-points">{items.map((p:any,i:number)=><div className="point" key={`${p.id}-${i}`}><div className="point-num">{i+1}</div><div><b>{p.name}</b><p>停留 {p.stay_minutes||0} 分钟</p></div><span className="point-tag">{i===0?'入口':i===items.length-1?'出口':'故事节点'}</span></div>)}</div>{!route&&<div className="api-status"><Sparkles size={15}/>当前没有可展示的后端路线，请返回重新生成。</div>}<button className="primary full" onClick={()=>go('story')} disabled={!route}>听听这条路线的故事 <BookOpen size={17}/></button></div></div>
}
;(RoutePageV2 as any)=RoutePageV3

function StoryGeneratorPageV3({s,go}:{s:State;go:(p:Page)=>void}){
  const animal=animals[s.companion]||animals[0]
  const [mode,setMode]=useState<StoryMode>('detective')
  const [story,setStory]=useState<any>(null)
  const [open,setOpen]=useState(0)
  const [busy,setBusy]=useState(true)
  const [source,setSource]=useState('')
  const [error,setError]=useState('')
  const route=(()=>{try{return JSON.parse(localStorage.getItem('hs-last-route')||'null')?.route}catch{return null}})()
  const rebuild=async(next:StoryMode)=>{
    setMode(next);setOpen(0);setBusy(true);setError('')
    if(!route?.ordered_pois?.length){setBusy(false);setStory(null);setSource('');setError('请先完成路线规划，再生成与路线绑定的故事');return}
    try{
      const result=await generateStoryApi({companion:animal.name,current_poi:route?.ordered_pois?.[0]?.name||'园区入口',route:route?.ordered_pois||[],collected_clues:s.clues,completed_npcs:s.stamps,style:next,persona:forestIdentity(s)})
      setStory(result.story);setSource(result.source)
    }catch{setError('故事服务暂时不可用，请检查后端连接');setStory(null)}finally{setBusy(false)}
  }
  useEffect(()=>{rebuild(mode)},[mode])
  return <div className="page generated-story"><div className="generated-head"><p className="eyebrow">STORY AGENT · 路线驱动 · 百炼</p><h1>把今天的路线，<br/>变成一场真正的故事</h1><p>故事会读取你的动物搭子、路线节点、已收集线索和 NPC 进度。</p></div><div className="story-input-summary"><div className="story-mini-mascot"><Companion3D size="tiny"/></div><div><b>{animal.name} × {route?.route_mode||s.routeMode}</b><small>{route?.ordered_pois?.length||0} 个真实路线节点 · {source||'等待故事 Agent'}</small></div><button className="icon-btn" onClick={()=>rebuild(mode)}><RotateCcw size={16}/></button></div><p className="eyebrow mode-label">选择故事风格</p><div className="mode-tabs mode-tabs-six">{storyModeOptions.map(x=><button className={mode===x.mode?'active':''} key={x.mode} onClick={()=>setMode(x.mode)}><span className="mode-icon">{x.icon}</span><b>{x.label}</b><small>{x.sub}</small></button>)}</div>{busy&&<div className="api-status"><Sparkles size={15}/>百炼正在根据你的路线编排故事…</div>}{error&&<div className="api-status">{error}</div>}{story&&<><div className="generated-cover"><span className="case-number">{source==='bailian_story_agent'?'BAILIAN':'LOCAL'}</span><p className="eyebrow">{story.modeLabel}</p><h2>{story.title}</h2><p>{story.hook}</p><div className="cover-meta"><span>真实路线驱动</span><span>动物搭子：{animal.name}</span><span>{source==='bailian_story_agent'?'百炼生成':'本地兜底'}</span></div></div><div className="story-timeline"><div className="timeline-title"><span>沿路线解锁故事</span><b>{open+1} / {story.chapters.length}</b></div>{story.chapters.map((ch:any,i:number)=><div className={`generated-chapter ${i===open?'open':''} ${i<open?'done':''}`} key={`${ch.point}-${i}`}><button onClick={()=>setOpen(i)}><span className="timeline-index">{i<open?'✓':`0${i+1}`}</span><span><b>{ch.point}</b><small>{ch.label}</small></span><ChevronRight size={17}/></button>{i===open&&<div className="chapter-detail"><p>{ch.text}</p><div className="mission"><Sparkles size={15}/><span><b>到达这里时做一件事</b><small>{ch.action}</small></span></div>{i<story.chapters.length-1?<button className="next-chapter" onClick={()=>setOpen(i+1)}>我找到线索了，继续 <ArrowRight size={15}/></button>:<div className="final-note">最后一站会回收开场悬念，并留下你的故事印记。</div>}</div>}</div>)}</div><div className="generated-ending"><Leaf size={19}/><p>{story.ending}</p></div><button className="primary full" onClick={()=>go('tour')}>带着这条故事出发 <ArrowRight size={17}/></button></>}</div>
}
;(StoryGeneratorPage as any)=StoryGeneratorPageV3

const venueGuides:Record<string,string>={
  gate:'这里是今天故事的入口。先确认游园时间和体力，再决定要不要走得更深。红山不是把动物一一展示给你，而是邀请你进入它们的生活边界。请不投喂、不敲玻璃、不追逐，把安静作为第一份入园礼物。',
  noah:'这里是路线中的水边节点。请先看水面、岸边植物和周围的声音，再寻找动物身影。水域不是一张静止的风景画，植物、昆虫和小型动物共同维持着它的变化。',
  panda:'来到金陵大熊猫苑，可以先观察它选择了室内还是室外、靠近树荫还是停在安静处。大熊猫不需要一直面对游客，按自己的节奏休息、进食和活动，本身就是最值得理解的讲解。',
  spirit:'这里是亚洲灵长馆。观察灵长类时，可以留意它们如何分配距离、目光和动作：群体中的关系不只靠叫声，也靠彼此熟悉的信号。请不要敲击玻璃，让它们决定是否回应你的到来。',
  rest:'这里是林间休息区，也是路线节奏的缓冲点。坐下来听一会儿，你可能会发现树叶声、脚步声和动物声音并不是背景，而是红山这段生境自己的层次。休息不是离开故事，而是让故事继续。',
  native:'这里是本土动物观察节点。貉、獐等城市野生动物并不需要成为游客面前的主角，真正的观察是辨认它们留下的痕迹，并给它们保留不被打扰的距离。',
  exit:'这里是路线的收束点。带走的不只是看过哪些动物，也包括你今天如何靠近、如何等待、如何把一段安静还给森林。'
}

function VenueV5({s,setS,go}:{s:State;setS:React.Dispatch<React.SetStateAction<State>>;go:(p:Page)=>void}){
  const p=points[s.active];const a=animals[s.companion]||animals[0]
  const [q,setQ]=useState('');const [answer,setAnswer]=useState('');const [busy,setBusy]=useState(false);const [listening,setListening]=useState(false)
  const guideText=`${a.name}：${venueGuides[p.id]||`${p.name}是今天路线中的一个观察节点。${p.sub}请先安静观察，再决定是否继续前进。`}`
  const ask=async(text=q)=>{if(!text.trim())return;setBusy(true);try{const r=await askCompanion({question:text,context:`当前点位：${p.name}。点位讲解：${guideText}`,companion:a.name});setAnswer(r.answer)}catch{setAnswer(answerFromKnowledge(`${p.name} ${text}`).answer)}finally{setBusy(false)}}
  const speak=async()=>{const text=answer||guideText;try{const r=await synthesizeSpeech(text);if(r.enabled&&r.audio_base64){const audio=new Audio(`data:${r.mime_type||'audio/mpeg'};base64,${r.audio_base64}`);await audio.play();return}}catch{}if('speechSynthesis'in window)window.speechSynthesis.speak(new SpeechSynthesisUtterance(text))}
  const listen=()=>{const w=window as Window&{webkitSpeechRecognition?:new()=>any};if(!w.webkitSpeechRecognition){setListening(true);setTimeout(()=>setListening(false),1200);return}const rec=new w.webkitSpeechRecognition();rec.lang=localStorage.getItem('hs-language')||'zh-CN';setListening(true);rec.onresult=(e:any)=>{const text=e.results[0][0].transcript;setQ(text);setListening(false);ask(text)};rec.onend=()=>setListening(false);rec.start()}
  const next=()=>{if(s.active>=4)go('complete');else setS(v=>({...v,active:v.active+1,page:'tour'}))}
  return <div className="page venue-live"><button className="language-pill" onClick={()=>{const next=localStorage.getItem('hs-language')==='en'?'zh-CN':'en';localStorage.setItem('hs-language',next);location.reload()}}>{localStorage.getItem('hs-language')==='en'?'EN':'中'} · language</button><div className="venue-hero"><div className="venue-symbol"><Leaf/></div><p className="eyebrow">已到达路线节点 {s.active+1}/5 · {p.name}</p><h1>{p.name}</h1><div className="active-chip"><i/> {a.name} 正在为你讲解这一站</div></div><div className="live-guide"><div className="guide-top"><Companion3D size="tiny"/><div><b>{a.name} 的现场讲解</b><small>点位专属讲解 · 由百炼 CosyVoice 朗读</small></div><button className="play" onClick={speak}><Play fill="currentColor" size={15}/></button></div><p>{guideText}</p><div className="audio-line"><i/></div></div><div className="ask-companion"><div className="ask-companion-head"><Sparkles size={16}/><b>想问这一站什么？</b><span>点位上下文 · 百炼 Qwen</span></div><div className="voice-row"><button className={`voice-btn ${listening?'listening':''}`} onClick={listen}><Mic size={20}/></button><input value={q} onChange={e=>setQ(e.target.value)} onKeyDown={e=>e.key==='Enter'&&ask()} placeholder={listening?'正在听你说…':`问问${p.name}的动物、场馆或故事`}/><button className="send-btn" onClick={()=>ask()}><ArrowRight size={17}/></button></div>{answer&&<div className="companion-answer"><Companion3D size="tiny"/><div><b>{a.name} 回答你</b><p>{busy?'正在查找这一站的资料…':answer}</p><button className="secondary" onClick={speak}>朗读回答</button><small>回答已带入当前点位上下文</small></div></div>}<div className="question-chips">{['这里最值得观察什么？','为什么不能敲玻璃？','这和自然有什么关系？'].map(x=><button key={x} onClick={()=>{setQ(x);ask(x)}}>{x}</button>)}</div></div><div className="observe"><Leaf size={18}/><span><b>不打扰地观察</b><small>不敲玻璃 · 不投喂 · 不使用强闪光 · 动物休息时请耐心等待</small></span></div><button className="primary full" onClick={next}>{s.active>=4?'完成游览':'继续下一站'} <ArrowRight size={17}/></button></div>
}
;(VenueV4 as any)=VenueV5

function VenueV6({s,setS,go}:{s:State;setS:React.Dispatch<React.SetStateAction<State>>;go:(p:Page)=>void}){
  const p=points[s.active];const a=animals[s.companion]||animals[0];const mission=nodeMissions[s.active]||nodeMissions[0]
  const [q,setQ]=useState('');const [answer,setAnswer]=useState('');const [busy,setBusy]=useState(false)
  const guideText=`${a.name}：${venueGuides[p.id]||`${p.name}是今天路线中的观察节点。${p.sub}请先安静观察，再继续前进。`}`
  const ask=async()=>{if(!q.trim())return;setBusy(true);try{const r=await askCompanion({question:q,context:`当前点位：${p.name}。点位讲解：${guideText}`,companion:a.name});setAnswer(r.answer)}catch{setAnswer(answerFromKnowledge(`${p.name} ${q}`).answer)}finally{setBusy(false)}}
  const speak=async()=>{const text=answer||guideText;try{const r=await synthesizeSpeech(text);if(r.enabled&&r.audio_base64){new Audio(`data:${r.mime_type||'audio/mpeg'};base64,${r.audio_base64}`).play();return}}catch{}if('speechSynthesis'in window)window.speechSynthesis.speak(new SpeechSynthesisUtterance(text))}
  const finish=()=>setS((v:any)=>{const already=v.npcTasks.includes(s.active);const nextPage=s.active>=4?'complete':'tour';if(already)return {...v,page:nextPage,active:s.active>=4?s.active:s.active+1};const nextScore=v.score+30;const history=s.active>=4?[...(v.history||[]),{id:`${Date.now()}`,date:new Date().toLocaleDateString('zh-CN'),companion:a.name,routeMode:v.routeMode,points:points.slice(0,5).map(x=>x.name),clues:v.clues.length+1,score:nextScore}]:v.history;return {...v,page:nextPage,active:s.active>=4?s.active:s.active+1,npcTasks:[...v.npcTasks,s.active],stamps:[...v.stamps,mission.npc],clues:v.clues.includes(mission.clue)?v.clues:[...v.clues,mission.clue],score:nextScore,history}})
  return <div className="page venue-live"><button className="language-pill" onClick={()=>{const next=localStorage.getItem('hs-language')==='en'?'zh-CN':'en';localStorage.setItem('hs-language',next);location.reload()}}>{localStorage.getItem('hs-language')==='en'?'EN':'中'} · language</button><div className="venue-hero"><div className="venue-symbol"><Leaf/></div><p className="eyebrow">已到达路线节点 {s.active+1}/5 · {p.name}</p><h1>{p.name}</h1><div className="active-chip"><i/> {a.name} 正在为你讲解这一站</div></div><div className="live-guide"><div className="guide-top"><Companion3D size="tiny"/><div><b>{a.name} 的现场讲解</b><small>点位专属讲解 · 百炼 CosyVoice</small></div><button className="play" onClick={speak}><Play fill="currentColor" size={15}/></button></div><p>{guideText}</p><div className="audio-line"><i/></div></div><div className="ask-companion"><div className="ask-companion-head"><Sparkles size={16}/><b>想问这一站什么？</b><span>当前点位 · 百炼 Qwen</span></div><div className="voice-row"><input value={q} onChange={e=>setQ(e.target.value)} onKeyDown={e=>e.key==='Enter'&&ask()} placeholder={`问问${p.name}的动物、场馆或故事`}/><button className="send-btn" onClick={ask}><ArrowRight size={17}/></button></div>{answer&&<div className="companion-answer"><Companion3D size="tiny"/><div><b>{a.name} 回答你</b><p>{busy?'正在查找这一站的资料…':answer}</p><button className="secondary" onClick={speak}>朗读回答</button></div></div>}<div className="question-chips">{['这里最值得观察什么？','为什么不能敲玻璃？','这和自然有什么关系？'].map(x=><button key={x} onClick={()=>{setQ(x);setTimeout(ask,0)}}>{x}</button>)}</div></div><div className="observe"><Leaf size={18}/><span><b>不打扰地观察</b><small>不敲玻璃 · 不投喂 · 不追逐 · 给动物保留自己的节奏</small></span></div><button className="primary full" onClick={finish}>{s.active>=4?'完成游览':'完成这一站，获得 +30 成长值'} <ArrowRight size={17}/></button></div>
}
;(VenueV4 as any)=VenueV6

type VenueGuideCard={intro:string;observe:string;why:string;clue:string;question:string}
const venueGuideCards:Record<string,VenueGuideCard>={
  gate:{intro:'先别急着赶路。红山的第一件展品不是某一种动物，而是这座山本身：树冠、坡度、风向和游客的脚步，共同决定了今天的森林节奏。',observe:'站在入口安静十秒：看一看树影往哪边移动，听一听最远处和最近处各有什么声音。',why:'把注意力从“我要看什么”换成“这里正在发生什么”，你会更容易发现红山不是一条展览走廊，而是一片有层次的山林。',clue:'入口的风把一小片叶子送向了更深处——故事从“慢一点”开始。',question:'如果只用一种感官开启今天的游园，你会选择看、听还是闻？'},
  noah:{intro:'到了水边，先不要寻找动物。池塘是一张会变化的关系网：水面反光、岸边植物、昆虫和水鸟，都在告诉你这里是否保持着自己的循环。',observe:'先看水面，再看水线附近的植物；最后听十秒，分辨是风声、水声，还是动物发出的声音。',why:'湿地的价值不只在“有没有一只好看的动物”，更在于它能不能给许多生命提供食物、躲藏和繁殖的空间。',clue:'水边留下了一个没有被打扰的空位，搭子说：真正的目击，有时从没有看见开始。',question:'你观察到的第一个变化，是水面的变化、植物的变化，还是声音的变化？'},
  panda:{intro:'熊猫馆值得看的不只是“熊猫出现了没有”，而是它怎样安排自己的一天：选择阴凉还是开阔处，什么时候进食，什么时候把身体交给休息。',observe:'找一个不挡住别人视线的位置，观察它的姿势和移动路线；如果它背对游客，也请把这当作它正在表达的需要。',why:'好的动物展示不是让动物持续表演，而是让它可以按自己的节奏生活。温度、遮荫、食物和空间，都会影响它的选择。',clue:'竹叶被折成了一个小小的方向标，指向“尊重选择”这条线索。',question:'如果搭子今天不想见你，你觉得怎样才算一次好的拜访？'},
  spirit:{intro:'灵长类动物的故事，藏在群体关系里。你可以观察它们怎样保持距离、互相回应，又怎样在热闹的群体中给自己留出安静的位置。',observe:'选择一个个体，连续观察它三次动作：它在看谁、回应谁，又在什么时候结束互动。',why:'灵长类的交流不只有叫声，目光、姿态、触碰和退让同样重要。保持距离，才能看见它们真实的关系。',clue:'一声短促的叫声没有得到追问，群体很快恢复了自己的秩序。',question:'你看到的是一次邀请、一次拒绝，还是一次保持距离？'},
  rest:{intro:'这里不是路线的空白，而是让观察重新变清楚的地方。停下来以后，树叶声、脚步声和远处动物的声音会慢慢分出层次。',observe:'坐下或站定半分钟，把刚才经过的两个点位各说出一个不同之处。',why:'休息会改变游览的节奏，也会改变你和搭子对线索的判断。很多细节只有在身体不再赶路时才会出现。',clue:'刚才被忽略的声音在这里重新出现，说明线索并没有消失，只是需要你停下来。',question:'如果把刚才的路线画成一条声音地图，你会把哪里标成最安静？'},
  native:{intro:'本土动物保育区讲的是“和城市一起生活”的动物。貉、狐狸等动物不一定总会出现在最显眼的位置，但它们留下的脚印、气味、食痕和活动时间，都是存在的证据。',observe:'不要追着找动物，试着找边缘：灌木下、土坡旁、树根附近，哪里更像是动物自己选择的通道？',why:'保育不是把动物变成景观，而是让它们保留选择栖息、躲藏和与人保持距离的权利。',clue:'灌木边缘有一条没有被踩乱的小路，搭子把它标记为“给野生动物留下的路”。',question:'如果你是一只生活在城市边缘的动物，最需要人类留下什么？'},
  exit:{intro:'走到出口，今天的故事还没有结束。你带走的不是看过几种动物，而是一次次靠近、等待和退让之后，对“如何与自然相处”的新判断。',observe:'回想一个你没有拍照、没有敲玻璃、只是安静等待的瞬间。',why:'红山的价值会随着游客离园继续发生：当你把不打扰带回城市，动物福利和自然教育才真正离开了园区。',clue:'最后一枚印记没有盖在地图上，而是盖在你的选择里：把看见变成长期的照顾。',question:'今天哪一次“没有打扰”，让你觉得自己真正参与了游园？'}
}

function VenueV7({s,setS,go}:{s:State;setS:React.Dispatch<React.SetStateAction<State>>;go:(p:Page)=>void}){
  const p=points[s.active]||points[0];const a=animals[s.companion]||animals[0];const mission=nodeMissions[s.active]||nodeMissions[0];const card=venueGuideCards[p.id]||venueGuideCards.gate
  const [q,setQ]=useState('');const [answer,setAnswer]=useState('');const [busy,setBusy]=useState(false);const [listening,setListening]=useState(false)
  const guideText=`${a.name}：${card.intro} ${card.observe} 这一站的线索是：${card.clue}`
  const ask=async(text=q)=>{if(!text.trim())return;setBusy(true);try{const r=await askCompanion({question:text,context:`当前点位：${p.name}。点位专属讲解：${guideText}。观察重点：${card.why}`,companion:a.name});setAnswer(r.answer)}catch{setAnswer(answerFromKnowledge(`${p.name} ${text}`).answer)}finally{setBusy(false)}}
  const speak=async()=>{const text=answer||guideText;try{const r=await synthesizeSpeech(text);if(r.enabled&&r.audio_base64){const audio=new Audio(`data:${r.mime_type||'audio/mpeg'};base64,${r.audio_base64}`);await audio.play();return}}catch{}if('speechSynthesis'in window)window.speechSynthesis.speak(new SpeechSynthesisUtterance(text))}
  const listen=()=>{const w=window as Window&{webkitSpeechRecognition?:new()=>any};if(!w.webkitSpeechRecognition){setListening(true);setTimeout(()=>setListening(false),1200);return}const rec=new w.webkitSpeechRecognition();rec.lang=localStorage.getItem('hs-language')||'zh-CN';setListening(true);rec.onresult=(e:any)=>{const text=e.results[0][0].transcript;setQ(text);setListening(false);ask(text)};rec.onend=()=>setListening(false);rec.start()}
  const finish=()=>setS((v:any)=>{const already=v.npcTasks.includes(s.active);const nextPage=s.active>=4?'complete':'tour';if(already)return {...v,page:nextPage,active:s.active>=4?s.active:s.active+1};return {...v,page:nextPage,active:s.active>=4?s.active:s.active+1,npcTasks:[...v.npcTasks,s.active],stamps:[...v.stamps,mission.npc],clues:v.clues.includes(mission.clue)?v.clues:[...v.clues,mission.clue],score:v.score+30}})
  return <div className="page venue-live"><div className="venue-hero"><div className="venue-symbol"><Leaf/></div><p className="eyebrow">已到达路线节点 {s.active+1}/5 · {p.name}</p><h1>{p.name}</h1><div className="active-chip"><i/> {a.name} 正在带你观察这一站</div></div><div className="live-guide"><div className="guide-top"><Companion3D size="tiny"/><div><b>{a.name} 的点位讲解</b><small>这一站只讲这一站 · 可语音朗读</small></div><button className="play" onClick={speak}><Play fill="currentColor" size={15}/></button></div><p>{guideText}</p><div className="audio-line"><i/></div></div><section className="guide-detail"><div><b>先观察什么</b><p>{card.observe}</p></div><div><b>为什么重要</b><p>{card.why}</p></div><div className="guide-clue"><b>带走这一站的线索</b><p>{card.clue}</p></div></section><div className="ask-companion"><div className="ask-companion-head"><Sparkles size={16}/><b>想问这一站什么？</b><span>点位上下文 · 百炼 Qwen</span></div><div className="voice-row"><button className={`voice-btn ${listening?'listening':''}`} onClick={listen}><Mic size={20}/></button><input value={q} onChange={e=>setQ(e.target.value)} onKeyDown={e=>e.key==='Enter'&&ask()} placeholder={listening?'正在听你说…':card.question}/><button className="send-btn" onClick={()=>ask()}><ArrowRight size={17}/></button></div>{answer&&<div className="companion-answer"><Companion3D size="tiny"/><div><b>{a.name} 回答你</b><p>{busy?'正在查找这一站的资料…':answer}</p><button className="secondary" onClick={speak}>朗读回答</button></div></div>}<div className="question-chips">{['这里最值得观察什么？','这和自然有什么关系？'].map(x=><button key={x} onClick={()=>{setQ(x);ask(x)}}>{x}</button>)}</div></div><div className="observe"><Leaf size={18}/><span><b>不打扰地观察</b><small>不敲玻璃 · 不投喂 · 不追逐 · 给动物保留自己的节奏</small></span></div><button className="primary full" onClick={finish}>{s.active>=4?'完成游览':'完成这一站，获得 +30 成长值'} <ArrowRight size={17}/></button></div>
}
;(VenueV4 as any)=VenueV7

function CompleteV2({go}:{go:(p:Page)=>void}){const score=latestState?.score||0;const tasks=latestState?.npcTasks?.length||0;return <div className="page complete-page"><div className="complete-mark"><Leaf size={32}/></div><p className="eyebrow">A GENTLE DAY IN HONGSHAN</p><h1>这一段路线，<br/>已经留下了你的印记。</h1><p className="lead">你完成了 {tasks} 个节点任务，收集了 {latestState?.clues?.length||0} 条线索。</p><div className="score"><b>+{tasks*30}</b><span>本次获得成长值 · 当前 {score}</span><div className="score-line"><i style={{width:`${Math.min(100,score/1.8)}%`}}/></div></div><div className="gains"><span>完成 NPC 节点任务 <b>{tasks}</b></span><span>收集路线线索 <b>{latestState?.clues?.length||0}</b></span><span>获得节点印章 <b>{latestState?.stamps?.length||0}</b></span></div><button className="primary full" onClick={()=>go('growth')}>查看我的成长印记 <ArrowRight size={17}/></button><button className="secondary full" onClick={()=>go('home')}>回到首页</button></div>}
;(Complete as any)=CompleteV2

function forestIdentity(s:any){
  const preference=String(s.preference||'')
  const tasks=s.npcTasks?.length||0;const clues=s.clues?.length||0;const score=s.score||0
  const identity=tasks>=4||score>=120?'森林守护者':clues>=2?'线索记录者':preference.includes('孩子')?'亲子自然引导员':preference.includes('熊猫')||preference.includes('动物')?'动物观察员':'初访探索者'
  const relation=tasks>=4?'默契同行':tasks>=2?'开始信任':tasks>=1?'认识彼此':'第一次见面'
  const next=tasks>=4?180:tasks>=2?90:30
  return {identity,relation,next,tasks,clues,score,tags:[preference.includes('孩子')?'亲子同行':null,preference.includes('怕晒')?'树荫路线':null,preference.includes('熊猫')?'熊猫偏好':null,clues?'线索收集':null,tasks?'NPC 互动':null].filter(Boolean)}
}

function GrowthV4({s,go}:{s:State;go:(p:Page)=>void}){
  const a=animals[s.companion]||animals[0];const profile=forestIdentity(s)
  const progress=Math.min(100,profile.score/1.8);const season=profile.tasks>=2?'黄昏本土物种线':'夏日树荫观察计划'
  return <div className="page growth-v3"><div className="growth-v3-head"><Companion3D size="normal"/><div><p className="eyebrow">我的森林身份</p><h1>{profile.identity}</h1><p>{a.name} · {profile.relation}</p></div><span className="badge">持续成长</span></div><section className="identity-card"><div className="identity-card-top"><div><p className="eyebrow">今天的身份画像</p><h2>{profile.identity}</h2><p>你正在用自己的方式理解红山，而不是完成一张打卡清单。</p></div><div className="identity-seal">{profile.tasks>=4?'守':profile.clues>=2?'录':'行'}</div></div><div className="tag-row">{(profile.tags.length?profile.tags:['等待第一次游园']).map((x:any)=><span key={x}>{x}</span>)}</div></section><section className="level"><div><b>你和 {a.name} 的关系</b><span>{profile.score} 成长值</span></div><div className="level-line"><i style={{width:`${progress}%`}}/></div><small>下一阶段：{profile.next} 成长值 · {profile.relation}</small></section><div className="growth-v3-stats"><span><b>{profile.clues}</b>线索</span><span><b>{profile.tasks}</b>节点任务</span><span><b>{s.stamps.length}</b>森林印记</span></div><section className="story-season-card"><p className="eyebrow">游园之后 · 持续更新</p><h2>{season}</h2><p>{profile.tasks>=2?'你已经熟悉红山的白天路线，下一次可以在黄昏听见另一种森林。':'完成一次路线后，解锁你的第一份季节观察任务。'}</p><button className="secondary">查看本季任务 <ArrowRight size={15}/></button></section><section className="story-season-card membership-card"><p className="eyebrow">红山文化不止于红山</p><h2>把一次游园，带回日常</h2><p>每月一条城市自然观察任务、一个搭子故事和一次线下印记兑换。</p><div className="membership-meta"><span>季节故事</span><span>城市观察</span><span>文创兑换</span></div><button className="primary full" onClick={()=>go('home')}>开启持续游伴计划 <ArrowRight size={16}/></button></section><section className="stamp-book"><div className="section-head"><h3>我的红山文化档案</h3><span>{s.stamps.length}/5</span></div><div className="stamp-grid">{nodeMissions.map((m,i)=><div className={s.npcTasks.includes(i)?'earned':''} key={m.npc}><span>{s.npcTasks.includes(i)?'印':`0${i+1}`}</span><small>{m.npc}</small></div>)}</div></section><button className="secondary full" onClick={()=>go('home')}>回到首页</button></div>
}
;(GrowthV3 as any)=GrowthV4

function GrowthV5({s,go}:{s:State;go:(p:Page)=>void}){
  const a=animals[s.companion]||animals[0];const profile=forestIdentity(s);const progress=Math.min(100,profile.score/1.8)
  const reward=a.species.includes('\u677e\u9f20')?{icon:'\ud83c\udf30',name:'\u677e\u5b50\u7f50',unit:'\u9897\u677e\u5b50',next:'\u518d\u6536\u96c6\u4e00\u9897\u677e\u5b50'}:a.species.includes('\u8c89')?{icon:'\ud83c\udf42',name:'\u843d\u53f6\u7ebf\u7d22\u888b',unit:'\u7247\u843d\u53f6',next:'\u518d\u627e\u5230\u4e00\u7247\u7ebf\u7d22\u843d\u53f6'}:a.species.includes('\u718a\u732b')?{icon:'\ud83c\udf8b',name:'\u7af9\u7b0b\u7bee',unit:'\u679a\u7af9\u7b0b',next:'\u518d\u6536\u96c6\u4e00\u679a\u65b0\u9c9c\u7af9\u7b0b'}:a.species.includes('\u8d64\u72d0')?{icon:'\ud83e\udd8a',name:'\u6797\u7f18\u6545\u4e8b\u76d2',unit:'\u5f20\u6545\u4e8b\u5361',next:'\u518d\u53d1\u73b0\u4e00\u5f20\u6797\u7f18\u6545\u4e8b\u5361'}:{icon:'\ud83c\udf3f',name:'\u68ee\u6797\u89c2\u5bdf\u7f50',unit:'\u679a\u89c2\u5bdf\u5370\u8bb0',next:'\u518d\u5b8c\u6210\u4e00\u6b21\u6e29\u67d4\u89c2\u5bdf'}
  return <div className="page growth-v3">
    <div className="growth-v3-head"><Companion3D size="normal"/><div><p className="eyebrow">我的森林身份</p><h1>{profile.identity}</h1><p>{a.name} · {profile.relation}</p></div><span className="badge">持续成长</span></div>
    <section className="identity-card"><div className="identity-card-top"><div><p className="eyebrow">今天的身份画像</p><h2>{profile.identity}</h2><p>你正在用自己的方式理解红山，而不是完成一张打卡清单。</p></div><div className="identity-seal">{profile.tasks>=4?'守':profile.clues>=2?'录':'行'}</div></div><div className="tag-row">{(profile.tags.length?profile.tags:['等待第一次游园']).map((x:any)=><span key={x}>{x}</span>)}</div></section>
    <section className="companion-currency"><div className="currency-jar"><span>{reward.icon}</span><i></i><i></i><i></i></div><div className="currency-copy"><p className="eyebrow">{reward.name}</p><h2>{profile.score} <small>{reward.unit}</small></h2><p>每完成一次观察、线索或 NPC 任务，就会把一份小小的成长放进搭子的容器里。</p><div className="currency-progress"><i style={{width:`${progress}%`}}></i></div><small>{reward.next} · {profile.next} 成长值解锁下一阶段</small></div></section>
    <section className="level"><div><b>你和 {a.name} 的关系</b><span>{profile.score} 成长值</span></div><div className="level-line"><i style={{width:`${progress}%`}}/></div><small>下一阶段：{profile.next} 成长值 · {profile.relation}</small></section>
    <div className="growth-v3-stats"><span><b>{profile.clues}</b>线索</span><span><b>{profile.tasks}</b>节点任务</span><span><b>{s.stamps.length}</b>森林印记</span></div>
    <section className="story-season-card"><p className="eyebrow">游园之后 · 持续更新</p><h2>{profile.tasks>=2?'黄昏本土物种线':'夏日树荫观察计划'}</h2><p>你的积分不是冷冰冰的数字，而是搭子世界里可以被看见的成长。</p></section>
    <section className="stamp-book"><div className="section-head"><h3>我的红山文化档案</h3><span>{s.stamps.length}/5</span></div><div className="stamp-grid">{nodeMissions.map((m,i)=><div className={s.npcTasks.includes(i)?'earned':''} key={m.npc}><span>{s.npcTasks.includes(i)?'印':`0${i+1}`}</span><small>{m.npc}</small></div>)}</div></section>
    <button className="secondary full" onClick={()=>go('home')}>回到首页</button>
  </div>
}
function GrowthV6({s,go}:{s:State;go:(p:Page)=>void}){const history=s.history||[];return <div className="growth-history-wrap"><GrowthV5 s={s} go={go}/><section className="play-history"><div className="section-head"><h3>{'游玩历史'}</h3><span>{history.length}{' 次记录'}</span></div>{history.length===0?<p className="history-empty">{'完成一次完整路线后，这里会留下你的路线、搭子和线索。'}</p>:history.slice().reverse().map(item=><article className="history-item" key={item.id}><div className="history-date">{item.date}</div><div className="history-main"><b>{item.routeMode}</b><p>{item.companion} · {item.points.length}{' 个点位'} · {item.clues}{' 条线索'}</p></div><span className="history-score">+{item.score}</span></article>)}</section></div>}
;(GrowthV3 as any)=GrowthV6
function StoryGeneratorPageV4({s,go}:{s:State;go:(p:Page)=>void}){
  const animal=animals[s.companion]||animals[0];const [mode,setMode]=useState<StoryMode>('detective');const [story,setStory]=useState<any>(null);const [open,setOpen]=useState(0);const [decisions,setDecisions]=useState<Record<number,string>>({});const [busy,setBusy]=useState(true);const [source,setSource]=useState('');const [error,setError]=useState('')
  const route=(()=>{try{return JSON.parse(localStorage.getItem('hs-last-route')||'null')?.route}catch{return null}})()
  const rebuild=async(next:StoryMode)=>{setMode(next);setOpen(0);setDecisions({});setBusy(true);setError('');if(!route?.ordered_pois?.length){setBusy(false);setStory(null);setError('请先完成路线规划，再生成与路线绑定的故事');return}try{const r=await generateStoryApi({companion:animal.name,current_poi:route.ordered_pois[0]?.name,route:route.ordered_pois,collected_clues:s.clues,completed_npcs:s.stamps,style:next,persona:forestIdentity(s)});setStory(r.story);setSource(r.source)}catch{setStory(null);setError('故事服务暂时不可用，请检查后端连接')}finally{setBusy(false)}}
  useEffect(()=>{rebuild(mode)},[mode])
  const choose=(chapter:number,id:string)=>{setDecisions(v=>({...v,[chapter]:id}));if(chapter<((story?.chapters?.length||1)-1))setOpen(chapter+1)}
  const trusted=Object.values(decisions).filter(x=>x==='respect'||x==='trust').length
  return <div className="page generated-story"><div className="generated-head"><p className="eyebrow">STORY AGENT · 互动路线叙事</p><h1>不是看一篇故事，<br/>而是一起把它走出来</h1><p>每个节点都有线索、NPC任务和选择。你的判断会改变搭子对你的信任，也会改变结局。</p></div><div className="story-input-summary"><div className="story-mini-mascot"><Companion3D size="tiny"/></div><div><b>{animal.name} × {route?.route_mode||s.routeMode}</b><small>{route?.ordered_pois?.length||0} 个路线节点 · {source||'等待故事 Agent'}</small></div><button className="icon-btn" onClick={()=>rebuild(mode)}><RotateCcw size={16}/></button></div><p className="eyebrow mode-label">选择故事风格</p><div className="mode-tabs mode-tabs-six">{storyModeOptions.map(x=><button className={mode===x.mode?'active':''} key={x.mode} onClick={()=>rebuild(x.mode)}><span className="mode-icon">{x.icon}</span><b>{x.label}</b><small>{x.sub}</small></button>)}</div>{busy&&<div className="api-status"><Sparkles size={15}/>百炼正在根据路线编排互动故事…</div>}{error&&<div className="api-status">{error}</div>}{story&&<><div className="generated-cover"><span className="case-number">{source==='bailian_story_agent'?'BAILIAN':'LOCAL'}</span><p className="eyebrow">{story.modeLabel}</p><h2>{story.title}</h2><p>{story.hook}</p><div className="cover-meta"><span>核心谜题</span><span>{story.core_mystery||'沿路线寻找答案'}</span></div></div><div className="story-timeline"><div className="timeline-title"><span>路线中的互动章节</span><b>{open+1} / {story.chapters.length}</b></div>{story.chapters.map((ch:any,i:number)=><div className={`generated-chapter ${i===open?'open':''} ${i<open?'done':''}`} key={`${ch.point}-${i}`}><button onClick={()=>setOpen(i)}><span className="timeline-index">{i<open?'✓':`0${i+1}`}</span><span><b>{ch.point}</b><small>{ch.label} · {decisions[i]?'已做出选择':'等待你的判断'}</small></span><ChevronRight size={17}/></button>{i===open&&<div className="chapter-detail"><p>{ch.scene||ch.text}</p><div className="fact-card"><Leaf size={17}/><span><b>这一站的线索</b><small>{ch.clue||'观察一个现场细节'}</small></span></div><div className="mission"><Sparkles size={15}/><span><b>NPC 任务</b><small>{ch.npc_task||ch.action}</small></span></div><p className="next-hint">下一站提示：{ch.next_hint||'把线索带到下一站'}</p><div className="story-branch-title">你准备怎么判断？</div><div className="story-branch-options">{(ch.choices||[{id:'observe',label:'继续观察',effect:'保留当前线索'},{id:'trust',label:'相信搭子',effect:'搭子更信任你'}]).map((choice:any)=><button className={decisions[i]===choice.id?'chosen':''} key={choice.id} onClick={()=>choose(i,choice.id)}><b>{choice.label}</b><small>{choice.effect}</small></button>)}</div>{decisions[i]&&<div className="branch-result">你选择了“{(ch.choices||[]).find((x:any)=>x.id===decisions[i])?.label||decisions[i]}”。这个判断会被带到下一站。</div>}</div>}</div>)}</div><div className="generated-ending"><Leaf size={19}/><p>{trusted>=2?'你多次把主动权交还给搭子，最后得到了一段只有耐心才能听见的答案。':story.ending}</p></div>{story.possible_endings&&<div className="possible-ending"><b>可能的结局</b>{story.possible_endings.map((x:string,i:number)=><span key={i}>{i+1}. {x}</span>)}</div>}<button className="primary full" onClick={()=>go('tour')}>带着这条互动故事出发 <ArrowRight size={17}/></button></>}</div>
}
;(StoryGeneratorPage as any)=StoryGeneratorPageV4

export default App
function AskV3({go}:{go:(p:Page)=>void}){const [q,setQ]=useState('');const [answer,setAnswer]=useState('');const [source,setSource]=useState('');const [busy,setBusy]=useState(false);const companion=(()=>{try{const raw=JSON.parse(localStorage.getItem('hs-state')||'{}');return animals[raw.companion||0]?.name||'团团'}catch{return '团团'}})();const ask=async(text=q)=>{if(!text.trim())return;setBusy(true);try{const r=await askCompanion({question:text,context:`红山动物园全园问答。当前搭子是${companion}，请保持它的专属人格。`,companion});setAnswer(r.answer);setSource(r.source)}catch{const r=answerFromKnowledge(text);setAnswer(r.answer);setSource(r.sources.length?'local_knowledge':'fallback')}finally{setBusy(false)}};return <div className="page ask-page"><p className="eyebrow">BAILIAN RAG · 红山知识库</p><h1>问问{companion}</h1><p className="ask-lead">{companion}会用自己的方式回答关于动物、场馆和保育的问题。</p><div className="ask-input"><input value={q} onChange={e=>setQ(e.target.value)} onKeyDown={e=>e.key==='Enter'&&ask()} placeholder="例如：这里最值得观察什么？"/><button onClick={()=>ask()}><ArrowRight size={18}/></button></div>{answer&&<div className="rag-result"><div className="rag-badge"><BookOpen size={15}/> {source==='bailian'?'已由百炼知识问答生成':'本地知识兜底回答'}</div><p>{busy?'正在检索红山知识库…':answer}</p></div>}<button className="secondary full ask-back" onClick={()=>go('home')}>回到首页</button></div>}
;(AskV2 as any)=AskV3
